"Am Nordkai liegt der Frachter „Seeschwalbe“ mit Kessars gefälschten Uniformen und Sprengstoff. Schleich dich mit Weber über das Terminal, markiere die Container und hol den erpressten Kapitän heraus – ohne Alarm.":"货轮“海燕号”停在北码头，载着凯萨的伪造制服和炸药。与韦伯潜行穿过码头，标记集装箱并救出被勒索的船长——不能触发警报。",
"Am Schießstand Hohenfeld lernst du unter Oberfeldwebel Krell alles, was die Kampagne verlangt: Bewegung, Waffen, Granaten, Ausrüstung, Befehle an den Trupp und den Geländewagen. Jeder Schritt wartet auf dich.":"在霍恩费尔德靶场，克雷尔二级军士长会教你战役所需的一切：移动、武器、手雷、装备、小队指令和越野车。每一步都会等你完成。",
"Am Vorderschaft: Gewehr beidhändig führen (einhändig streut es stark). An der Brust: Granate nehmen, Abzug zieht den Splint, Loslassen wirft.":"握在护木上：双手持枪（单手散布很大）。在胸前：取手榴弹，扳机拔销，松手投掷。",
