"Amboss an Falke 2 und Kiesel: Die Korvaner halten die Brücken von Mirenfurt. Wir nehmen die Stadt zurück – Haus für Haus.":"铁砧呼叫猎鹰2号和卵石：科尔瓦尼亚人控制着米伦富特的桥梁。我们要逐屋夺回这座城市。",
"Amboss an Falke 2: Ihr habt Feuerfreiheit ab der Sperrlinie. Viel Glück.":"铁砧呼叫猎鹰2号：过了封锁线可自由开火。祝好运。",
"Amboss an Falken: Aufklärung meldet zwanzig Fahrzeuge im Anmarsch auf die Höhe. Die Kompanie braucht noch eine halbe Stunde.":"铁砧呼叫猎鹰：侦察报告有二十辆车正向高地逼近。连队还需要半小时。",
"Amboss an alle Falken: Auftrag erfüllt. Sammeln am Markt. Ende.":"铁砧呼叫所有猎鹰：任务完成。在集市集合。完毕。",
"Amboss an alle Falken: Korvanische Panzer haben um vier Uhr die Grenze bei Mirenfurt überschritten. Vor uns liegt ihre Sperrlinie.":"铁砧呼叫所有猎鹰：科尔瓦尼亚坦克四点钟在米伦富特越过边境。我们前方就是他们的封锁线。",
"Amboss: Die Kompanie ist auf der Höhe. Der Feind zieht sich zurück.":"铁砧：连队已到达高地。敌人正在撤退。",
"Amboss: Funkstelle ist still. Gut gemacht, Graufalken. Die Artillerie schießt jetzt ins Leere.":"铁砧：电台已沉默。干得好，灰鹰。他们的炮兵现在只能盲射。",
"Amboss: Lager und Brücke brennen. Der Hauptverband steht ohne Treibstoff.":"铁砧：营地和桥都在燃烧。敌军主力断了燃料。",
