"Anker an Eisen-Zug: Aufklärung meldet feindliche Pioniere an der Flussbrücke. Dazu mindestens zwei Kampfpanzer.":"锚点呼叫铁排：侦察报告河桥有敌方工兵，另有至少两辆主战坦克。",
"Anker an Falke: Das Relais schweigt. Keine Sendung ist hinausgegangen. Ich wiederhole: keine Sendung.":"锚点呼叫隼：中继站沉默了。没有任何广播发出。重复：没有广播。",
"Anker an Geleit: Die Kommission erwartet Major Daren um neunzehn Uhr am Nordhang. Die Straße durchs Dorf ist frei gemeldet.":"锚点呼叫护航组：委员会将于十九点在北坡等待达伦少校。据报穿村道路畅通。",
"Anker an Kapelle: Die Delegationen sind unterwegs. Ankunft in etwa zwanzig Minuten. Bewegung im Trichterfeld nördlich von euch.":"锚点呼叫小教堂：代表团已在路上。约二十分钟后抵达。你们北边的弹坑区有动静。",
"Anker an Libelle 1: Kessars Maschine wird auf dem Vorfeld betankt. Abflug in etwa zwanzig Minuten. Zwei Flugabwehrstellungen gemeldet.":"锚点呼叫蜻蜓 1 号：凯萨的飞机正在停机坪加油。约二十分钟后起飞。报告有两处防空阵地。",
"Anker an Libelle 1: Luftraum frei. Zwei Jäger fliegen das Vorfeld an.":"锚点呼叫蜻蜓 1 号：空域已清空。两架战斗机正飞向停机坪。",
"Anker an Trupp Falke: Das Relais von Sant Aurel sendet einen Prüfton. In elf Minuten geht Kessars Botschaft an alle Einheiten beider Seiten.":"锚点呼叫隼小队：圣奥雷尔中继站正在发送测试音。十一分钟后凯萨的消息将发给双方所有部队。",
"Anker an Trupp Falke: Funkspruch vom Fliegerhorst Hagenmoor. Die Graue Kompanie hält zwanzig Leute vom Bodenpersonal in den Unterkünften fest.":"锚点呼叫隼小队：哈根莫尔空军基地来电。灰色连队把二十名地勤人员扣在营房里。",
"Anker an Trupp Falke: Peilung bestätigt. Die Stimme sendet vom Funkhügel, jede Nacht um zwei Uhr, immer nur vierzig Sekunden.":"锚点呼叫隼小队：测向已确认。那个声音从电台山发出，每晚两点，每次只有四十秒。",
"Anker an Trupp Lenz: Der Frachter Seeschwalbe liegt seit gestern Abend am Nordkai. Ladung laut Papieren: Ersatzteile.":"锚点呼叫伦茨小队：货轮“海燕号”从昨晚起停靠在北码头。文件上写的货物：备件。",
"Anker an Trupp Lenz: Im Staatsarchiv brennt seit einer Stunde Licht. Niemand hat die Wachablösung gemeldet.":"锚点呼叫伦茨小队：国家档案馆的灯已经亮了一个小时。没人报告换岗。",
"Anker an Werk Sieben: Busse und Lkw sind unterwegs. Erste Abfahrt in vier Minuten.":"锚点呼叫七号工厂：大巴和卡车正在路上。四分钟后首批出发。",
"Anker an alle Einheiten: Das Funkrelais Sant Aurel sendet seit drei Stunden nicht mehr. Keine Verbindung ins Tal.":"锚点呼叫所有单位：圣奥雷尔无线电中继站已经三小时没有信号。与河谷失去联系。",
"Anker an alle Einheiten: Starke Kräfte der Brigade Kessar vor der Nordstellung. Infanterie, Panzer, mindestens zwei Bataillone.":"锚点呼叫所有单位：北阵地前出现凯萨旅的大量兵力。步兵、坦克，至少两个营。",
"Anker an alle: Das Funkhaus von Veldmark ist besetzt. Kessar hält die Belegschaft fest. Die Straßen füllen sich – die Stadt geht zur Arbeit.":"锚点呼叫全体：费尔德马克广播大楼被占领。凯萨扣押了员工。街上人越来越多——全城都在上班路上。",
"Anker an alle: Der Brand oberhalb des Holzplatzes breitet sich nach Süden aus. Funkkontakt zu den Arbeitern abgerissen.":"锚点呼叫全体：木材场上方的火势正向南蔓延。与工人的无线电联系中断。",
"Anker an alle: Die Brigade Kessar weicht zurück. Ich wiederhole: Sie weichen zurück!":"锚点呼叫全体：凯萨旅正在后撤。重复：他们在后撤！",
"Anker an alle: Kessars Verbände ziehen sich auf breiter Front zurück. Die Linie hält.":"锚点呼叫全体：凯萨的部队正在全线撤退。防线守住了。",
"Anker an alle: Sitzung der Waffenstillstandskommission beginnt um zwölf Uhr. Etwa dreihundert Menschen auf dem Lindenplatz.":"锚点呼叫全体：停火委员会会议十二点开始。林登广场上约三百人。",
"Anker hat mitgehört. Gute Arbeit, Falke. Wir verlegen sofort zum Werk und bringen die Leute dort raus.":"锚点都听到了。干得好，隼。我们马上转往工厂，把那里的人撤出来。",
