"Anker hier. Zwei Jäger sind in der Luft. Markiert uns die Kolonne, dann schlagen sie zu.":"锚点呼叫。两架战斗机已升空。给我们标记车队，他们就会打击。",
"Anker hier: Druck in der Talleitung ist stabil. Die Pumpen laufen.":"锚点呼叫：河谷主管道压力稳定。水泵正常运转。",
"Anker hört euch. Was braucht ihr?":"锚点收到。你们需要什么？",
"Anker: Geleit hat den Nordhang erreicht. Der Zeuge ist unverletzt.":"锚点：护航组已抵达北坡。证人毫发无伤。",
"Anker: Kessars Maschine brennt. Der Flugplatz ist in unserer Hand.":"锚点：凯萨的飞机着火了。机场在我们手里。",
