"Arcade zeigt dir alles und heilt schnell. Realistisch blendet Gegner und fast das ganze HUD aus und macht Treffer tödlicher. Simulation geht noch weiter: Magazine, Durchladen, Ladehemmungen, Verwundungen, kein HUD. Der Vergleich steht unter":"街机显示所有信息且恢复快。写实会隐藏敌人和几乎全部 HUD，命中更致命。模拟更进一步：弹匣、上膛、卡壳、伤势，没有 HUD。对比见",
