"Arcade: W/A/S/D fahren, Maus richten, Linksklick Feuer, 1–4 Munition.":"街机：W/A/S/D 驾驶，鼠标瞄准，左键开火，1–4 选弹。",
"Arcade: das bekannte Spiel. Realistisch: keine Gegneranzeigen, minimales HUD, mehr Schaden, langsamere Heilung.":"街机：熟悉的玩法。写实：无敌人标记、极简 HUD、伤害更高、恢复更慢。",
