"Auf den meisten aktuellen Handys ja, auf der Grafikstufe „Niedrig“ oder „Mittel“. Das Handy quer halten. Nötig ist ein Browser mit WebGL 2. Die Übersicht steht unter":"大多数新款手机可以，画质为“低”或“中”。请横屏握持。需要支持 WebGL 2 的浏览器。概览见",
"Auf der rechten Hälfte ziehen. Optional Gyro (Einstellungen → Steuerung).":"在右半边拖动。可选陀螺仪（设置 → 操作）。",
"Auf eine Meile":"一英里外",
"Auf fünfzig Meter und weiter: hinlegen, anlegen, ruhig atmen.":"五十米及以外：卧倒、瞄准、平稳呼吸。",
"Auf vielen echten Grafikkarten war plötzlich der Boden unsichtbar. Der Grund: Der Gelände-Shader brauchte 17 Texturen, dort sind aber nur 16 erlaubt. In der Testumgebung fiel das nicht auf, weil sie 32 erlaubt. Der Hotfix kam noch am selben Abend. In den Tagen davor waren neue Ego-Hände und neue Körper für die Soldaten entstanden. Danach Akt III der Kampagne mit den Missionen 12 bis 15 und die Panzersimulation: vier Plätze, jeder Handgriff selbst, mit Tutorial, Hilfe oder ganz frei.":"在许多真实显卡上，地面突然看不见了。原因是：地形着色器需要 17 张纹理，但那里只允许 16 张。测试环境中没有发现，因为它允许 32 张。当晚就发布了热修复。在此之前几天，士兵们有了新的第一人称手部和新身体。之后是战役第三幕的第 12 至 15 号任务，以及坦克模拟：四个岗位，每个操作亲力亲为，可选教程、提示或完全自由。",
"Auf welchem Gerät?":"在什么设备上？",
