"Auf {0}{1}m: Gleichstand, beide {2}.":"{0}{1}米处：平局，均为 {2}。",
"Aufgesetzt. Nicht schön, aber heil. Raus mit euch – ich bleibe beim Hubschrauber.":"着陆了。不好看，但完好无损。下去吧——我留在直升机这儿。",
