"Auflösung der Fotoscan-Texturen (Böden, Wände, Holz, Metall). Ultra lädt 2048er-Scans: deutlich schärfer aus der Nähe, braucht mehr Grafikspeicher und Ladezeit. Nur auf Qualitätsstufe Hoch/Ultra und nicht auf Telefonen. Gilt ab dem nächsten Match.":"照片扫描纹理（地面、墙壁、木材、金属）的分辨率。极高加载 2048 扫描：近看明显更清晰，但占用更多显存和加载时间。仅在高/极高画质且非手机时可用。下一局生效。",
