"Bleibt die Frage, um die es bei dem Experiment eigentlich geht: Merkt man einem Spiel heute noch an, dass eine KI den Code geschrieben hat? Wenn es dir beim Spielen nicht aufgefallen ist, ist das vielleicht schon die Antwort.":"剩下的就是这个实验真正要问的问题：如今还能看出一款游戏的代码是 AI 写的吗？如果你在游玩时没有察觉，这也许就是答案。",
"Bleibt geduckt und im Schatten. Die Wachen gehen Streife – wartet, bis sie euch den Rücken zudrehen.":"压低身子，待在阴影里。守卫在巡逻——等他们背对你们再动。",
