"Bullpup mit 50-Schuss-Magazin, das quer über dem Lauf liegt. Auf Türrahmen-Distanz die schnellste Waffe im Arsenal – dahinter verpufft ihre Wirkung rasch.":"无托结构，50 发弹匣横置于枪管上方。门框距离内是军械库中最快的武器——再远效果迅速下降。",
"Bullpup mit integrierter 1,6-fach-Optik: voller Gewehrlauf in kompaktem Gehäuse, präzise bis weit über die Platzmitte. Das Magazin sitzt hinter dem Griff – der Wechsel dauert.":"集成 1.6 倍瞄具的无托步枪：紧凑机身中的全尺寸枪管，精准射程远超广场中央。弹匣位于握把后方——换弹较慢。",
"Bullpup-Sturmgewehr mit Rotpunkt: langer Lauf im kurzen Gehäuse, ruhig im Dauerfeuer und präzise bis weit über die Straße. Das Magazin hinter dem Griff will geübt gewechselt werden.":"配红点的无托突击步枪：短机身长枪管，连射稳定，精准射程可跨越整条街。握把后的弹匣需要练习才能快速更换。",
