"Da ist er – mit zwei, drei Mann Leibwache. Nicht auf Kessar schießen, Falke! Nur die Wachen!":"他在那儿——带着两三个保镖。别打凯萨，隼！只打保镖！",
"Da kauert er, hinter dem Marktstand. Er hebt die Hände – nimm ihn fest, Falke!":"他蹲在市场摊位后面。举手了——抓住他，隼！",
"Da oben – der Gittermast und der Bunker. Fünf Mann, vielleicht mehr im Bunker. Die Sendung beginnt in zehn Minuten.":"上面——铁塔和地堡。五个人，地堡里可能更多。广播十分钟后开始。",
