"Das Match konnte nicht gestartet werden.":"无法开始对局。",
"Das Profil ist nicht verfügbar. Spielen geht trotzdem.":"档案不可用。仍可游玩。",
"Das Vorfeld brennt. Die Hallen sind noch besetzt – rein da, Raum für Raum.":"停机坪烧起来了。厂房里还有人——冲进去，逐屋清剿。",
"Das Wasser ist eiskalt. Bleibt in Bewegung, dann merkt man es nicht.":"水冰冷刺骨。一直走就感觉不到了。",
"Das Werkstor ist gefallen – die Lkw kommen nicht mehr heraus.":"厂门失守——卡车出不去了。",
"Das alte Walzwerk liegt still im Nachmittagslicht. Sonnenbahnen fallen durch die staubigen Hallenfenster, Laufstege ziehen sich unter dem zerbrochenen Hallendach entlang, und zwischen Pressen, Rohrbrücken und den Ladebuchten der Lkw wartet hinter jeder Ecke ein Hinterhalt. Oben kontrollierst du die Halle – unten entscheidet der schnellste Abzug.":"老轧钢厂在午后阳光中一片寂静。阳光透过布满灰尘的厂房窗户洒下，走道沿破损的屋顶延伸，在压力机、管廊和卡车装卸区之间，每个拐角都可能有埋伏。在上面你能控制整个厂房——在下面，谁扣扳机快谁就赢。",
"Das bisherige Spiel: volles HUD, Namensschilder, Gegner auf der Minikarte, schnelle Regeneration.":"熟悉的玩法：完整 HUD、名牌、小地图显示敌人、快速回血。",
"Das hat er gespürt! Noch einmal!":"他感觉到了！再来一次！",
"Das ist nicht die Fassung, die wir verteilt haben. Das ist die geänderte. Und das ist Ansgars Handschrift.":"这不是我们发的那版。这是改过的。而且这是安斯加的笔迹。",
"Das ist sein Transporter! Bevor der in der Luft ist – Feuer frei!":"那是他的运输机！趁它还没升空——自由开火！",
"Das kann der Pionier nicht bauen.":"工兵造不了这个。",
"Das kleinere Team kehrt schneller ins Gefecht zurück.":"人数少的队伍更快重返战斗。",
"Das sind sie. Die Originale. Beide Unterschriften, beide Siegel. Kessars Papiere sind dagegen nichts wert.":"就是这些。原件。双方签名，双方印章。凯萨的文件在它们面前一文不值。",
"Das volle Spiel als Programm: Grafikstufe":"完整游戏程序：画质等级",
"Das war erst die Vorhut. Der Hauptverband kommt über die Höhe beim alten Flugplatz – und wir sind die Einzigen, die dort stehen.":"那只是先头部队。主力正从老机场旁的高地过来——而那里只有我们。",
"Das war ihr Anführer. Jaro Vahl. Und hier, auf dem Rechner: Sitzordnung, Zeitplan, Fluchtwege. Für Veldmark. Für morgen Mittag.":"那是他们的头目，亚罗·瓦尔。电脑里有：座位表、时间表、撤离路线。针对费尔德马克。明天中午。",
"Das war ordentlich, Falk. Der Rest kommt draußen – mit jedem Tag.":"做得不错，法尔克。剩下的会在外面一天天学会。",
