"Den Funker lebend festnehmen":"活捉通信兵",
"Den Gegner ausgeschaltet, der dich zuletzt erwischt hat.":"击杀了上一次击杀你的敌人。",
"Den Jagdpanzer im Hinterhalt finden":"找到埋伏的坦克歼击车",
"Den Panzer an der Straße ausschalten":"击毁路边的坦克",
