"Den hat keiner von uns je gesehen. Er spricht nur über Funk. Und er hat schon für den Fall bezahlt, dass ich heute verliere.":"我们谁都没见过他。他只通过无线电说话。而且他已经为我今天失败的情况付过钱了。",
"Den holen wir mit raus. Falke, du gehst mit Weber rein. Ich decke euch vom Südtor und bringe das Boot.":"我们把他也带出来。隼，你和韦伯进去。我在南门掩护你们，并把小艇开过来。",
