"Der Abzug ist tot: Klopfen (Magazin sitzt?), Ziehen (Spannhebel ganz durch), Kanten – die klemmende Patrone fliegt heraus.":"扳机没反应：拍（弹匣插好了吗？）、拉（拉机柄拉到底）、侧倾——卡住的子弹就会掉出来。",
"Der Anlasser orgelt den Diesel etwa zwei Sekunden, dann läuft der Motor im Leerlauf.":"启动机带动柴油机约两秒，随后引擎怠速运转。",
"Der Auerochs startet beim ersten Versuch, Herr Oberfeldwebel. Alt, aber ehrlich.":"“Auerochs”一次就打着了，军士长。老是老，但靠得住。",
"Der Boden war weg.":"地面不见了。",
