"Der Controller, mit dem du gerade spielst, wird erkannt, die Symbole passen sich an (Xbox, PlayStation, Nintendo). Der TV-Modus vergrößert Schrift und Bedienflächen für den Abstand zum Fernseher.":"会识别你正在使用的手柄，按键图标随之适配（Xbox、PlayStation、Nintendo）。电视模式会放大文字和操作区域，适合远距离观看。",
"Der Feldspaten des Grabenkämpfers: zwei Hiebe mit der geschärften Kante. Spezial „Graben“: auf Großkarten hebt jeder Schlag in den Erdboden Erde aus – eigene Schützenlöcher, Gräben und Schächte, so tief man will. Der Pionier trägt ihn zusätzlich als eigene Waffe (Mausrad).":"堑壕战士的工兵铲：用磨利的铲刃劈两下。特殊“挖掘”：在大地图上每一铲下去都能挖出泥土——自己的散兵坑、战壕和竖井，想挖多深挖多深。工兵另外将其作为独立武器携带（鼠标滚轮）。",
"Der Funker ist raus – Richtung Torhaus und Marktgasse! Wir brauchen ihn lebend, Falke!":"通信兵跑了——往门楼和市场巷去了！要活的，隼！",
"Der Funker ist unbewaffnet – schalte seine Begleiter aus, nicht ihn.":"通信兵没有武器——解决他的同伙，别打他。",
"Der Funker wurde getroffen. Wir brauchten ihn lebend.":"通信兵被击中了。我们需要活口。",
"Der Gegner hat kaum noch Tickets.":"敌方兵力点所剩无几。",
"Der Gegner hält die Stellung.":"敌方控制着据点。",
"Der Geländewagen steht am Ende der Bahnen. Einsteigen, Runde fahren.":"越野车停在靶道尽头。上车，开一圈。",
"Der Grenzvertrag ist unterschrieben. Von beiden Seiten. In einer Ruine, unter Beschuss, aber unterschrieben.":"边境条约签了。双方都签了。在废墟里、在炮火下，但签了。",
"Der Grenzvertrag wird in der Kapellenruine unterschrieben. Grab dich mit dem Klappspaten ein, bau Sandsackwälle und halte die Ruine gegen die Graue Kompanie, bis die Delegationen fertig sind.":"边境条约在小教堂废墟签署。用工兵铲挖掘工事，筑起沙袋墙，抵御灰色连队守住废墟，直到代表团完成签署。",
"Der Heuboden-Zwerg":"草料棚小矮人",
