"Der Host würfelt beim Start":"房主在开局时随机",
"Der JK-9 ist verloren.":"JK-9 损失了。",
"Der Kapitän ist weg! Alle Mann zum Kaibüro!":"船长不见了！所有人去码头办公室！",
"Der Keil schließt – erst jetzt ist die Kanone feuerbereit.":"炮闩楔块闭合——此时火炮才可射击。",
"Der Kommandant ist in diesem Spiel ausgeschaltet (Lobby: Modus-Einstellung „Kommandant“).":"本局已关闭指挥官（大厅：模式设置“指挥官”）。",
"Der Kommandant weist Ziele zu und befiehlt „Feuer!“.":"车长分配目标并下令“开火！”。",
"Der Laser misst die Zielentfernung; Strichplatte und Rechner setzen den Haltepunkt.":"激光测出目标距离；分划板和计算机给出瞄准点。",
"Der Letzte. Zugriff – jetzt!":"最后一个。抓——现在！",
"Der Mann mit dem Funkgerät hatte das hier in der Tasche. Die Sitzordnung. Mit Kreuzen an den Plätzen der Delegationen.":"拿对讲机的人口袋里有这个。座位表。代表团的位置上画着叉。",
"Der Munitionsbunker im Turmheck ist durch eine Schiebetür vom Kampfraum getrennt (Sprengklappen nach außen).":"炮塔尾舱弹药舱与战斗室之间由滑门隔开（泄压板朝外）。",
"Der Parcours. Durch das Fenster – nicht durch die Tür.":"障碍场。从窗户走——不是门。",
"Der Plan für den Mehrspieler.":"多人模式的计划。",
"Der Platz liegt zwischen uns und dem Funkhaus. Sie haben Schützen auf den Dächern.":"广场横在我们和广播大楼之间。他们屋顶上有枪手。",
"Der Raum ist voll. Frag den Host, ob er mehr Plätze freigibt – oder such dir ein anderes Spiel.":"房间已满。请让房主开放更多位置——或另找一局。",
