"Der Rechner muss die geladene Munition kennen, sonst stimmen Haltepunkt und Entfernungsmarken nicht. Verschossen wird immer die tatsächlich geladene Granate.":"火控计算机必须知道已装填的弹种，否则瞄准点和距离标记都不准。发射的始终是实际装填的炮弹。",
"Der Ring füllt sich mit jedem Abschuss.":"每次击杀都会填充圆环。",
"Der SP-6 „Moloch“ hält Panzergranaten von vorn aus. Über die Flanke fahren und die Seite treffen.":"SP-6“Moloch”正面能扛住穿甲弹。绕到侧翼，打它侧面。",
"Der Satzbau ist ausgefallen.":"句子构建器出错了。",
"Der Sender steht im Turm, wie beim ersten Mal. Eingang auf der Westseite.":"发射机在塔里，和第一次一样。入口在西侧。",
"Der Spielprozess ist zuletzt abgestürzt ({0}, {1}). „Extrem“ nutzt deshalb 4K- statt 8K-Schatten.":"游戏进程上次崩溃了（{0}，{1}）。因此“极致”画质改用 4K 阴影而非 8K。",
"Der Standard: realistisches Licht und natürliche Körperbewegung, nur ein Hauch Objektiv und Rauschen.":"默认：写实光照与自然身体动作，只带一点镜头效果和噪点。",
"Der Text ist kopiert. Öffne Discord und schick ihn an":"文本已复制。打开 Discord 并发送给",
"Der Wagen ist da! Alle rein – ich zähle durch!":"车到了！全上车——我点人数！",
"Der Wagen mit Major Daren darf nicht ausfallen":"载达伦少校的车不能有失",
"Der Wagen mit Major Daren wurde zerstört.":"载着达伦少校的车被摧毁了。",
"Der Wahlhebel steht auf „Sicher“ – der Abzug ist blockiert. Weiterschalten: Einzelfeuer, dann (falls vorhanden) Feuerstoß/Dauerfeuer, dann wieder Sicher.":"快慢机处于“保险”——扳机被锁住。依次切换：单发，然后（如有）点射/全自动，再回到保险。",
"Der Wald oberhalb der Dörfer brennt. Falk fliegt als Bordschütze im Hubschrauber „Libelle 1“ mit, hält die Landezone frei und wird mit Lenz abgesetzt. Am Boden sammeln sie die Dorfbewohner und ziehen sich vor Feuer und Feind Linie um Linie zur Landezone zurück. Im letzten Flug entschlüsselt Weber: Kessar greift mit allem an – im Niemandsland.":"村庄上方的森林在燃烧。法尔克作为舱门机枪手搭乘直升机“蜻蜓 1 号”，守住着陆区，随后与伦茨一同机降。地面上他们集合村民，在大火和敌人面前一道防线一道防线地撤向着陆区。最后一次起飞时，韦伯破译出：凯萨倾巢而出——在无人区。",
"Der Wind dreht nach Süden. Das Feuer kommt schneller, als uns lieb ist.":"风向转南了。火来得比我们希望的快。",
"Der dritte Kranich ist noch unbekannt. Neue Kapitel erscheinen mit kommenden Updates und stellen neue Karten, Waffen und Fahrzeuge vor.":"第三只“鹤”仍然身份不明。新章节将随后续更新推出，并带来新的地图、武器和载具。",
"Der dritte: auch eine Warnweste, ganz vorn an der Absperrung zur Allee. Er hat ein Funkgerät in der Jackentasche.":"第三个：也穿反光背心，在靠大道的隔离栏最前面。他外套口袋里有部对讲机。",
"Der entscheidende letzte Abschuss des Matches.":"本局决定胜负的最后一击。",
"Der erste Abschuss des Matches.":"本局第一次击杀。",
"Der gelbe Container am Kranplatz. Zwei Wachen, eine geht Streife.":"起重机场的黄色集装箱。两名守卫，一个在巡逻。",
"Der große Test.":"大测试。",
"Der große Umbau.":"大改造。",
"Der korvanische Hauptverband will über die Höhe am alten Flugplatz ins Tal. Halte mit Falke 1 die Stellung, bis die Kompanie heran ist – drei Wellen aus Panzern, Schützenpanzern und Panzerabwehrtrupps.":"科尔瓦尼亚主力想经老机场旁的高地进入河谷。与猎鹰1号一起坚守阵地直到连队赶到——三波坦克、步兵战车和反坦克小组。",
"Dezember":"十二月",
"Dichte Nebelwand für sechzehn Sekunden: Deckung zum Überqueren, Vorrücken, Bergen. Bots sehen nicht hindurch – du auch nicht.":"浓密烟幕持续十六秒：掩护穿越、推进、救援。机器人看不穿——你也看不穿。",
