"Doppelflinte mit Kipplauf: zwei Läufe, zwei Abzüge, zwei Schuss – dann wird geknickt. Auf Raumlänge endgültig, im Doppelschuss bis über die Hofmitte.":"折开式双管霰弹枪：两根枪管、两个扳机、两发——然后折开装填。室内距离一击毙命，双响可打到院子中间以外。",
