"Dorf ist ruhig. Lagemeldung, Leutnant?":"村子安静了。报告情况，少尉？",
"Dorf ist sauber. Ein paar Leute im Keller der Kapelle – denen geht es gut.":"村子肃清了。小教堂地窖里有几个人——他们没事。",
