"Dr. Pell ist nicht in der U-Bahn angekommen. Er ist beim ersten Schuss in den Hauseingang am Nordplatz gegangen – und dann war er weg.":"佩尔博士没有到达地铁。第一声枪响时他走进了北广场的一个门洞——然后就不见了。",
"Dr. Pell wurde getroffen. Wir schießen nur, wenn wir sicher sind.":"佩尔博士被击中了。我们只在确认时开火。",
"Drehe Front zum Feind!":"正面转向敌人！",
