"Drei Angriffswellen abwehren (Süden, Westhof, beide)":"击退三波进攻（南面、西院、两面同时）",
"Drei Angriffswellen abwehren, die Ruine nie aufgeben":"击退三波进攻，绝不放弃废墟",
