"Drei Flaggen in einem Leben eingenommen.":"一条命内占领三面旗帜。",
"Drei Flaggen. Halte zwei, und die Uhr arbeitet für dich.":"三面旗帜。守住两面，时间就站在你这边。",
"Drei Keramikplatten. Der Standard für den Sturm: hält, ohne zu bremsen.":"三块陶瓷插板。突击兵标配：防护而不拖慢速度。",
