"Drei Panzer in breiter Front. Ich nehme den linken.":"三辆坦克宽正面展开。我打左边那辆。",
"Drei Panzerabwehrwerfer gegen Fahrzeuge und Bunker, dazu Truppführer und Schütze.":"三具反坦克火箭筒对付载具和地堡，另有小队长和步枪手。",
"Drei Wochen Waffenruhe, und jemand will sie brechen. Zwischensequenzen mit deutscher Lippensynchronisation, Checkpoints, gespeicherter Fortschritt. Akt III endet offen, weitere Kapitel folgen.":"三周的停火，有人想打破它。带口型同步的过场动画、检查点、进度保存。第三幕以开放式结局收尾，后续章节敬请期待。",
"Drei Wochen Waffenruhe, und jetzt das. Jemand will, dass wir blind und taub sind.":"停火三周，现在出了这事。有人想让我们又瞎又聋。",
"Drei Wochen Waffenruhe. Ein Mann, der sie brechen will.":"停火三周。有人想打破它。",
"Drei Wochen vor dem Ende der Waffenruhe":"停火结束前三周",
"Drei Wochen vor dem Ende der Waffenruhe: Unteroffizier Falk frischt am Schießstand Hohenfeld unter Oberfeldwebel Krell alles auf, was er im Einsatz brauchen wird – vom ersten Schritt bis zum Befehl an den Trupp und der Fahrt im Geländewagen.":"停火结束前三周：法尔克上士在霍恩费尔德靶场，在克雷尔二级军士长指导下复习作战所需的一切——从第一步到向小队下令，再到驾驶越野车。",
