"Du bist Ladeschütze. Befohlene Munition laden und entsichern.":"你是装填手。装填命令的弹种并解除保险。",
"Du bist MG-Schütze und Funker. Funkgerät auf Kanal 5, durch die Kugelblende (RMT) zielen, Feuerstöße auf Infanterie.":"你是机枪手兼无线电员。电台调到 5 频道，通过球形枪座（右键）瞄准，对步兵点射。",
"Du bist Richtschütze. Waffe scharf schalten, dann in die Hauptzieloptik (Sicht wechseln).":"你是炮手。先让武器待发，再切到主瞄准镜（切换视角）。",
