"Du bist unverletzt.":"你没有受伤。",
"Du blutest. Ein Verband stillt Streifschüsse und mindert schwere Blutungen. Erst in Deckung gehen – die Waffe ist dabei weg.":"你在流血。包扎能止住擦伤出血并减缓大出血。先找掩体——包扎时武器会收起。",
"Du fliegst! Fahrwerk kommt von selbst. Jetzt such dir die zwei Begleiter – die schießen auf alles, was sich Seyfried nähert.":"你飞起来了！起落架会自动收起。现在找到那两架护航——它们会攻击任何靠近赛弗里德的东西。",
"Du fliegst: W/S steigen/sinken · A/D drehen · Maus neigen · Leertaste schweben (Gamepad: linker Stick, rechter Stick, A).":"你来飞：W/S 升降 · A/D 转向 · 鼠标倾斜 · 空格悬停（手柄：左摇杆、右摇杆、A）。",
"Du fährst: Motor anlassen, Bremse, Gang – die Befehle des Kommandanten stehen oben im Bild.":"你来驾驶：启动引擎、刹车、挂挡——车长的命令显示在画面上方。",
"Du führst einen eigenen Trupp aus vier bis neun Soldaten und steuerst einen davon – die anderen folgen dir und gehorchen dem Befehlsrad. Fällt dein Soldat, übernimmst du sofort einen Kameraden; erst wenn der ganze Trupp gefallen ist, wählst du einen neuen Trupp-Typ: Sturm, MG, Pioniere, Scharfschützen, Panzerabwehr, Panzerbesatzung oder Fahrzeugtrupp. Die Front verläuft über eine Kette von Punkten, die nur der Reihe nach fallen; jeder Einsatz kostet Verstärkung.":"你率领一支四到九人的小队并操控其中一人——其余队员跟随你并服从指令轮盘。你的士兵阵亡时可立即接管一名战友；只有全队阵亡后才选择新的小队类型：突击、机枪、工兵、狙击手、反坦克、坦克乘员或载具小队。前线由一串据点构成，只能依次攻占；每次部署都会消耗增援。",
"Du führst jetzt {0} (Schütze).":"你现在操控 {0}（步枪手）。",
"Du führst jetzt {0} ({1}).":"你现在操控 {0}（{1}）。",
"Du führst, Falke. Ich bin nur der mit dem kaputten Arm, der dir über die Schulter schaut.":"你带队，隼。我只是个胳膊坏了、在你身后看着的人。",
"Du führst.":"你领先。",
"Du führst: Ziele übergeben, Munition und Feuer befehlen, Fahrbefehle. Die Besatzung arbeitet selbst.":"你来指挥：移交目标、下令选弹和开火、下达行驶命令。车组自行操作。",
"Du gewinnst.":"你赢了。",
