"Du lädst jede Granate von Hand: wählen, greifen, einschieben, schließen, entsichern.":"你手动装填每一发炮弹：选择、拿取、推入、闭锁、解除保险。",
"Du richtest und schießt in der Hauptzieloptik; der Kommandant weist Ziele zu.":"你用主瞄准镜瞄准射击；车长分配目标。",
