"Einschusslöcher je Kaliber, Querschläger und Durchschüsse. Dauerfeuer frisst sich durch Wände, Sprengungen reißen begehbare Breschen mit gebrochenen Rändern, Ruß und Staub. Türen fallen aus zerschossenen Scharnieren, Bäume kippen, Panzer schieben Gebäude ein.":"弹孔随口径变化，有跳弹和贯穿。持续射击能打穿墙壁，爆炸会炸出可通行的缺口，边缘破碎，带着烟灰和尘土。铰链被打坏的门会掉落，树木会倒下，坦克能推倒建筑。",
"Einschüssiger 40-mm-Granatwerfer: Splittergranate im hohen Bogen, scharf ab 12 m. Räumt Fenster, Gräben und Stellungen.":"单发 40 毫米榴弹发射器：高抛破片榴弹，12 米外解除保险。清理窗户、战壕和阵地。",
"Einsteigen":"上车",
