"Einsteigen: F · Gamepad X · Touch: „Einsteigen“. Der Fahrersitz ist besetzt – du kommst ans MG.":"上车：F · 手柄 X · 触屏：“上车”。驾驶座有人——你去机枪位。",
"Einsteigen: {0} – der Pilotensitz ist belegt, du kommst an den Kinnturm.":"上机：{0}——驾驶座有人，你去机首炮塔。",
