"Eisen 1 fährt vorn. Die Kette ist geflickt – sie hält, solange niemand drauftritt.":"铁 1 号打头。履带补好了——只要没人踩上去就撑得住。",
"Eisen 1 hat einen Kettenschaden, der fährt heute nicht mehr. Also fährst du Eisen 2, Falke. Ich führe vom Funkgerät aus.":"铁 1 号履带损坏，今天开不了了。所以你开铁 2 号，隼。我在电台上指挥。",
"Eisen 1, komme von Süden. Ich habe gehört, ihr braucht einen Türsteher.":"铁 1 号，从南面过来。听说你们需要个看门的。",
