"Entstehung, Fragen, Rechte":"由来、问答、权利",
"Epilog: Ansprache am Sender – offenes Ende (Kranich, Phase zwei)":"尾声：电台讲话——开放式结局（鹤、第二阶段）",
"Episch":"史诗",
"Er brennt. Die Besatzung springt ab – lasst sie gehen.":"它烧起来了。乘员在跳车——让他们走。",
"Er droht nur. Er braucht die Leute im Haus lebend – sonst hört ihm niemand mehr zu.":"他只是在威胁。他需要楼里的人活着——不然没人会再听他说话。",
"Er gibt nicht auf. Er sucht sich nur ein lauteres Mikrofon.":"他没放弃。只是在找个更响的麦克风。",
"Er hebt die Hände. Nimm ihn fest, Falke – und ruf Hofer.":"他举手了。抓住他，隼——叫霍费尔来。",
"Er ist oben auf dem Dach, am Sendemast! Treppenhaus an der Ostseite!":"他在屋顶的发射塔旁！东侧楼梯间！",
"Er ist unten! Wir sind mit dem Wagen gleich da. Seyfried steigt aus – mit erhobenen Händen.":"他降落了！我们开车马上到。赛弗里德下来了——举着手。",
"Er nennt sie nur „Kranich“. Mehr weiß ich wirklich nicht.":"他只叫他们“鹤”。我真的就知道这么多。",
"Er sprengt heute Nacht die Brücke am Grenzfluss. Dann ist das Tal abgeschnitten – und alle werden Ihnen die Schuld geben.":"今晚他要炸掉边境河上的桥。那样河谷就被切断了——所有人都会把责任推到你们身上。",
"Er war nicht an Bord. Ein Wagen ist eben durchs Südtor gerast – Richtung Veldmark.":"他不在飞机上。刚有一辆车冲出南门——往费尔德马克去了。",
"Er war nie hier. Er sprach über eine Leitung aus dem Fliegerhorst Hagenmoor. Morgen früh fliegt er außer Landes – mit allem, was er über seine Geldgeber hat.":"他从来没在这儿。他是通过哈根莫尔空军基地的线路讲话的。明早他就要带着金主的所有资料飞出国。",
"Er wird langsamer. Einmal noch, dann hat er genug.":"他在减速。再来一次，他就受够了。",
"Er wusste, wo sie sitzen würden. Weil er sie dorthin gesetzt hat.":"他知道他们会坐在哪儿。因为是他安排的。",
