"Erobere die Flaggen A, B und C und halte sie gegen den Druck des Gegners. Jede gehaltene Flagge bringt Punkte – wer zuerst 150 erreicht, gewinnt. Abschüsse sind Mittel zum Zweck.":"占领 A、B、C 三面旗帜并顶住敌人压力。每面守住的旗帜都能得分——先到 150 者获胜。击杀只是手段。",
"Erobere und halte die Flaggen":"占领并守住旗帜",
