"Es gibt keine Munitionsanzeige. Magazin herausziehen, wiegen, ansehen – du bekommst nur eine Schätzung.":"没有弹药计数。拔出弹匣，掂一掂、看一看——你只能得到大概数量。",
"Es gibt nur eine Stellung – und sie bleibt nicht lange an einem Ort. Wer sie allein hält, bekommt jede Sekunde einen Punkt; stehen beide Teams drin, ist sie umkämpft und niemand punktet. Kurz vor dem Wechsel taucht die nächste Stellung gedimmt auf: Wer früh umsetzt, hat den besseren Winkel.":"只有一个据点，而且不会在同一位置停留太久。独占据点每秒得 1 分；双方都在其中时为争夺状态，无人得分。即将转移前，下一个据点会以暗色显示：提前转移就能占据更好的角度。",
