"Faktor für die senkrechte Achse – gilt für Maus, Controller, Touch und Gyro.":"垂直轴系数——适用于鼠标、手柄、触屏和陀螺仪。",
"Falk führt den Trupp":"法尔克带队",
"Falk übernimmt den Kampfpanzer „Eisen 2“, deckt die Infanterie im Dorf und kämpft die Brücke frei. Am Ende tritt Daren allein mit erhobenen Händen auf die Brücke und übergibt Kessars unterschriebene Befehle.":"法尔克接管主战坦克“铁 2 号”，掩护村中的步兵并打通大桥。最后达伦举着双手独自走上桥，交出凯萨签署的命令。",
"Falke 1":"猎鹰1号",
"Falke 1 (Asmus)":"猎鹰1号（阿斯穆斯）",
"Falke 1 getroffen – wir steigen aus! Falke 2, die Höhe gehört jetzt dir allein!":"猎鹰1号被击中——我们弃车！猎鹰2号，现在高地全靠你了！",
"Falke 1 ist liegen geblieben! Wir steigen aus – kämpft weiter, Falke 2!":"猎鹰1号瘫痪了！我们弃车——继续战斗，猎鹰2号！",
"Falke 1 möglichst nicht verlieren":"尽量不要失去猎鹰1号",
"Falke 1: Motorengeräusch jenseits der Brücke. Da kommt einer.":"猎鹰1号：桥对面有引擎声。有人来了。",
"Falke 2":"猎鹰2号",
"Falke 2, ihr fahrt allein. Falke 1 sichert den Rückweg.":"猎鹰2号，你们单独行动。猎鹰1号掩护返程。",
"Falke 2, ihr fahrt rechts von mir. Erst die Pak, dann alles, was sich bewegt. Die Funkstelle nehmen wir uns gemeinsam.":"猎鹰2号，你们在我右侧行进。先打反坦克炮，再打一切会动的。电台我们一起拿下。",
"Falke! Im Wagen liegt ein Donnerkeil. Nimm ihn – ich habe ihn dir in die Hand gedrückt.":"隼！车里有一具“雷霆”火箭筒。拿着——我已经塞到你手里了。",
"Falke, Lenz – Veldmark wacht gleich auf. Das Funkhaus im Stadtkern sendet in die ganze Region. Dahin will er.":"隼、伦茨——费尔德马克马上就要醒了。市中心的广播大楼覆盖整个地区。他就是要去那儿。",
"Falke, Lenz – das Relais im Glockenturm ist unsere einzige Leitung zu den Dörfern. Ich brauche es zurück.":"隼、伦茨——钟楼里的中继站是我们通往各村的唯一线路。我要把它夺回来。",
"Falke, bis Lenz zurück ist, führst du den Trupp.":"隼，在伦茨回来之前，由你带队。",
"Falke, das ist jetzt dein Trupp. Ich sage dir, was ich Lenz immer gesagt habe: Behalte die Leute im Blick, nicht nur den Feind.":"隼，现在这是你的小队了。我把一直跟伦茨说的话告诉你：要盯着自己的人，不只是敌人。",
"Falke, du führst. Ich folge dir diesmal.":"隼，你带队。这次我跟着你。",
"Falke, du gehst über die Treppe auf die Galerie und markierst jede Wache, die du siehst. Wir warten hier.":"隼，你从楼梯上回廊，标记你看到的每个守卫。我们在这儿等。",
"Falke, du sitzt am Kinnturm. Ich halte uns im Kreis, du räumst den Platz frei.":"隼，你操作机首炮塔。我绕圈飞，你清场。",
"Falke, du sitzt vorn am Kinnturm. Wenn mir unterwegs etwas zustößt, bringst du uns runter. Du weißt, wie das geht.":"隼，你坐前面的机首炮塔。路上我要是出事，你把我们降下去。你知道怎么做。",
"Falke, du stehst am MG im zweiten Wagen, Weber fährt. Achte auf alles, was sich in den Feldern bewegt.":"隼，你在第二辆车的机枪位，韦伯开车。注意田里任何动静。",
"Falke, mach dich bereit. Du fährst Eisen 2. Wir gehen an den Fluss.":"隼，准备一下。你开铁 2 号。我们去河边。",
"Falke, zu mir. Jetzt lernst du, uns zu führen.":"隼，过来。现在你来学怎么指挥我们。",
"Falke, zum Jäger! Er steht auf der Bahn, Westende. Einsteigen, Haube zu – den Rest erkläre ich dir.":"隼，去战斗机！在跑道西头。上去，关好座舱盖——剩下的我教你。",
