"Fassung des Zwiegesprächs":"对话版本",
"Fast alle Waffen nach echten Vorbildern neu gebaut, auch Werfer, Nahkampfwaffen und Granaten. 45 Oberflächen der Welt als echte Fotoscans, am Nachmittag 20 weitere. Soldaten mit modellierten Gesichtern und Mimik, Massenschlachten mit bis zu 250 Soldaten je Seite. Und die Kampagne „Stille Grenze“ begann: morgens drei Missionen mit Zwischensequenzen und deutscher Lippensynchronisation, abends die Grundausbildung und die Missionen 4 bis 6, kurz vor Mitternacht die Missionen 7 bis 11 bis zum offenen Ende von Akt II. Dazu zwei neue Karten, Flugplatz und Stadtkern, ein Jet, der von der Startbahn abhebt, und die Apps: PC-App, Web-App mit Offline-Speicher und Android.":"几乎所有武器都参照真实原型重新制作，包括发射器、近战武器和手榴弹。45 种世界表面采用真实照片扫描，下午又加了 20 种。士兵有了建模的面孔和表情，大规模战斗每方最多 250 名士兵。战役“寂静边境”也开始了：上午三个带过场动画和德语口型同步的任务，晚上是基础训练和第 4 至 6 号任务，午夜前不久是第 7 至 11 号任务，直到第二幕的开放式结局。另外还有两张新地图“机场”和“市中心”，一架能从跑道起飞的喷气机，以及应用：PC 应用、支持离线存储的网页应用和安卓应用。",
"Fast: ich, zusammen mit einer KI.":"差不多：是我和一个 AI 一起。",
