"Feine Schatten dort, wo Dinge den Boden berühren (Füße, Kisten, Leisten) – ergänzt die Schattenkarte. Ab „Hoch“.":"物体接地处的细微阴影（脚、箱子、踢脚线）——补充阴影贴图。“高”及以上。",
"Feld anklicken und eine Taste aus der Liste wählen. H = Haupthand (Waffe), N = Nebenhand. A/X ist die untere, B/Y die obere Taste.":"点击一栏并从列表中选择按键。H = 主手（武器），N = 副手。A/X 为下方键，B/Y 为上方键。",
"Feld anklicken, dann Taste oder Maustaste drücken. Esc bricht ab. Bis zu drei Belegungen je Aktion.":"点击一栏，然后按下按键或鼠标键。Esc 取消。每个动作最多三个绑定。",
