"Feldwebel … Anker meldet Rauch über dem Brandwald. Das ganze Waldstück oberhalb des Holzplatzes steht in Flammen.":"上士……锚点报告森林上空冒烟。木材场上方整片林子都烧起来了。",
"Feldwebel … ich habe Kessars Funk entschlüsselt. Er zieht alles zusammen, was ihm folgt. Morgen früh, im Niemandsland.":"上士……我破译了凯萨的无线电。他在集结所有追随者。明天早上，在无人区。",
"Feldwebel! Anker meldet: Das Funkrelais in Sant Aurel ist verstummt. Keine Verbindung mehr ins Tal.":"上士！锚点报告：圣奥雷尔的无线电中继站沉默了。与河谷失去联系。",
