"Für dieses Gerät empfohlen: {0}. Mehr Bots können ruckeln und das Gerät warm machen.":"本设备推荐：{0}。更多机器人可能导致卡顿和发热。",
"Für kleine Studios und für alle, die gerade erst anfangen, öffnet das eine Tür. Ein Spiel zu entwickeln verschlingt normalerweise viel Geld; selbst das größte Abo bei Claude ist günstiger als das, was die Entwicklung eines Indie-Spiels sonst kostet. Wer selbst programmieren kann, gibt dabei nichts aus der Hand: Er kann weiter eigene Wege gehen und prüfen, was die KI geschrieben hat. Und wer es nicht kann, so wie ich, bekommt überhaupt erst die Chance, aus einer Idee ein fertiges Spiel zu machen.":"对小工作室和所有刚刚起步的人来说，这打开了一扇门。开发一款游戏通常要花很多钱；即使是 Claude 最贵的订阅，也比开发一款独立游戏通常的花费便宜。会编程的人不会因此失去什么：他们依然可以走自己的路，并检查 AI 写了什么。而像我这样不会编程的人，才第一次有机会把一个想法变成一款完整的游戏。",
