"Greller Blitz und ohrenbetäubender Knall: Wer hinsieht, ist für Sekunden blind und hört nur noch Pfeifen. Schadet niemandem – außer dem Plan des Gegners.":"刺眼闪光和震耳巨响：看着它的人会失明数秒，只听见耳鸣。不伤任何人——除了敌人的计划。",
"Grelles Mittagslicht, gebleichter Putz und messerscharfe Schatten. Die Marktgasse duckt sich unter bunten Sonnensegeln, im Herzen der Stadt plätschert der alte Brunnen unter dem Glockenturm, und dahinter verzweigen sich schmale Gassen, Torbögen und Treppen hinauf zu den Dachterrassen. Wer die Dächer kennt, sieht alles zuerst – und wird selbst gesehen.":"刺眼的正午阳光、褪色的灰泥墙和锐利的阴影。市场巷隐藏在彩色遮阳篷下，城市中心的老喷泉在钟楼下潺潺作响，其后狭窄的小巷、拱门和台阶一路通向屋顶露台。熟悉屋顶的人最先看到一切——也会被别人看到。",
