"Großkalibrige Pistole mit sieben Patronen und spürbarem Hochschlag. Drei Treffer genügen auf kurze Distanz – zwei, wenn der erste den Kopf findet.":"大口径手枪，七发，上跳明显。近距离三发足矣——首发爆头则只需两发。",
"Großkampf auf weiter Karte: Nehmt die Flaggen A bis E ein, haltet sie und lasst den Gegner ausbluten. Jeder Wiedereinstieg kostet ein Ticket, wer mehr Flaggen hält, zieht dem Gegner laufend Tickets ab. Trupps zu viert, Einsatzkarte mit HQ-, Flaggen- und Truppspawns, Panzer und Geländewagen.":"广阔地图上的大规模战斗：占领 A 到 E 旗帜并坚守，让敌人流尽兵力。每次复活消耗一点兵力，旗帜多的一方会持续消耗敌方兵力。四人小队，部署地图可选总部、旗帜和小队复活点，还有坦克和越野车。",
