"Großkarte: Schützengräben, Granattrichter, Stacheldraht, Ruinen – fünf Flaggen.":"大地图：战壕、弹坑、铁丝网、废墟——五面旗帜。",
"Großkarte: Startbahn, Hangars, Tower, Tanklager, Radar, Kaserne – Jets starten vom Boden.":"大地图：跑道、机库、塔台、油库、雷达、营房——喷气机从地面起飞。",
"Großkarte: verbrannter Wald, Schützengräben mit Sandsäcken, Gittermasten – fünf Flaggen.":"大地图：焚毁的森林、沙袋战壕、铁塔——五面旗帜。",
