"Gut erkannt!":"猜对了！",
"Gut gehalten. Ihre Infanterie ist erschöpft – jetzt brauchen wir das Funkgerät, bevor die Panzer kommen.":"守得好。他们的步兵已经精疲力竭——现在得在坦克到来前拿回电台。",
"Gut gemacht, Falke. Du hast heute niemanden verloren. Ruht euch aus – um fünf Uhr fliegt ihr nach Hagenmoor. Lenz besteht darauf, mitzukommen.":"干得好，隼。今天你一个人都没丢。休息吧——五点飞往哈根莫尔。伦茨坚持要一起去。",
"Gut gemacht. Jetzt in die Löcher – und warten.":"干得好。现在进坑——等着。",
"Gut gemacht. Jetzt zum Tor – sie kommen gleich.":"干得好。现在去大门——他们马上就到。",
"Gut gemacht. Kommen Sie zum Vorplatz.":"干得好。到前院来。",
"Gut getroffen!":"打得好！",
"Gut so. Von hier siehst du den ganzen Nordplatz. Die Sitzung beginnt gleich.":"很好。从这儿能看到整个北广场。会议马上开始。",
"Gut zu wissen":"须知",
"Gut. Die nächste Welle ist schon unterwegs – mit Schützenpanzern und Infanterie.":"很好。下一波已经在路上——有步兵战车和步兵。",
"Gut. Jetzt schnell – sprinten Sie ein Stück.":"很好。现在快点——冲刺一段。",
"Gut. Motor läuft. Die Kanone ist geladen. Folge der Straße nach Süden.":"很好。引擎启动，主炮已装填。沿公路向南走。",
