"Haas":"哈斯",
"Haas ist unten in der U-Bahn! Sie ist unverletzt!":"哈斯已经下到地铁里了！她没受伤！",
"Haas lässt den Grenzvertrag nicht in einer Stadt unterschreiben, sondern dort, wo der Krieg am tiefsten Spuren hinterlassen hat: in der Kapellenruine im Niemandsland. Bis die Delegationen eintreffen, bleibt eine Stunde – Falk und der Trupp heben Schützenlöcher aus, bauen Sandsackwälle und halten die Ruine gegen die Graue Kompanie. Leutnant Roth bringt „Eisen 1“ für einen kurzen Gegenstoß. Vahl wird gefangen und nennt einen Namen: Konrad Seyfried, der auf dem Fliegerhorst Hagenmoor auf seinen Abflug wartet.":"哈斯没有选择在城市签署边境条约，而是在战争留下最深伤痕的地方：无人区的小教堂废墟。距代表团抵达还有一小时——法尔克和小队挖掘散兵坑、筑起沙袋墙，抵御灰色连队守住废墟。罗特少尉带来“铁 1 号”进行短暂反击。瓦尔被俘，并说出一个名字：康拉德·赛弗里德，他正在哈根莫尔空军基地等待起飞。",
"Haas sagt die Sitzung nicht ab. Sie sagt, wer sich vor Söldnern versteckt, hat schon verloren. Falke – du bekommst ein Dach und ein Gewehr.":"哈斯不取消会议。她说躲着雇佣兵的人已经输了。隼——你去屋顶，带上步枪。",
"Hab ihn. Wir nehmen ihn am Rand, ganz ruhig.":"盯住了。我们在边上悄悄带走他。",
"Hab sie. Mit der Liste kann ich ihre Befehle lesen, sobald das Relais wieder läuft.":"拿到了。中继站一恢复，我就能用这张表读他们的命令。",
