"Herbst im Tal der Miren. Mit „Falke 2“ und deiner Besatzung brichst du durch Sperrlinien, hältst eine Höhe, sicherst Nachschub und kämpfst bei Nacht mit Wärmebild. Eine Mission spielt achtzig Jahre früher in einem alten Panzer.":"米伦河谷的秋天。你和车组驾驶“猎鹰2号”突破封锁线、坚守高地、确保补给，并借助热成像夜战。其中一个任务发生在八十年前，驾驶一辆老式坦克。",
"Herbst im Tal der Miren: Korvanische Panzer überschreiten die Grenze. Mit „Falke 2“ und deiner Besatzung brichst du durch Sperrlinien, hältst eine Höhe, geleitest Nachschub und schlägst bei Nacht zu.":"米伦河谷的秋天：科尔瓦尼亚坦克越过边境。你和车组驾驶“猎鹰2号”突破封锁线、坚守高地、护送补给、夜袭敌后。",
"Herbst im Tal der Miren: Korvanische Panzer überschreiten die Grenze. Mit „Falke 2“ und deiner Besatzung brichst du durch Sperrlinien, hältst eine Höhe, geleitest Nachschub, schlägst bei Nacht zu – und erfährst, warum Oberfeldwebel Asmus die Furt von Mirenfurt so gut kennt.":"米伦河谷的秋天：科尔瓦尼亚坦克越过了边境。你和你的车组驾驶“猎鹰2号”突破封锁线、坚守高地、护送补给、夜袭敌后——并得知阿斯穆斯三级军士长为何对米伦富特渡口如此熟悉。",
"Herr Hauptmann – Kessar sendet. Auf allen Frequenzen gleichzeitig.":"上尉——凯萨在广播。所有频率同时。",
"Herr Hauptmann – jemand ist auf unserer Frequenz. Offener Kanal, ohne Schlüssel.":"上尉——有人在我们的频率上。公开频道，没加密。",
"Herr Hauptmann … jemand ist auf unserer offenen Frequenz. Kein Rufzeichen. Das Signal kommt nicht aus dem Tal.":"上尉……有人在我们的公开频率上。没有呼号。信号不是从河谷发出的。",
"Herr Hauptmann! Das Relais in Sant Aurel – Kessars Leute haben es besetzt. Er will heute Nacht senden, auf allen Kanälen.":"上尉！圣奥雷尔的中继站——被凯萨的人占了。他今晚要在所有频道上广播。",
