"Hier Vahl. Der Hügel ist verloren. Plan bleibt. Mittag, Lindenplatz. Niemand redet.":"我是瓦尔。山丢了。计划不变。中午，林登广场。谁都不许说。",
"Hier haben vor hundert Jahren Männer auf beiden Seiten in Gräben gelegen. Wenn wir hier unterschreiben, versteht jeder, worum es geht.":"一百年前，双方的人就在这里的战壕里。在这里签字，每个人都会明白这意味着什么。",
