"Hörst du das? Ein Kind weint, im Hausflur an der Gasse. Die Leute haben es nicht mehr in den Keller geschafft.":"你听到了吗？巷边楼道里有个孩子在哭。那家人没来得及躲进地窖。",
"Hört nicht hin. Wer heute hier steht, steht für seine Familie zu Hause, nicht für Kessar.":"别听他的。今天站在这里的人，是为了家里的亲人，不是为了凯萨。",
"Hüftstreuung":"腰射散布",
"Hülse klemmt im Auswurf!":"弹壳卡在抛壳口！",
"Ich":"我",
"Ich bin am Rechner! Gib mir eine Minute – und halt sie mir vom Leib!":"我在电脑这儿！给我一分钟——帮我挡住他们！",
"Ich bleibe bei ihnen. Geht ins Magazin.":"我陪着他们。你们去书库。",
"Ich bleibe hinter Ihnen, Unteroffizier. Gehen Sie voran.":"我跟在你后面，上士。你带路。",
"Ich brauche jeden, der tragen kann. Ich bleibe hier am Posten.":"我需要所有能抬人的人。我留在救护站。",
"Ich decke dich!":"我掩护你！",
"Ich fahre vorsichtig. Versprochen.":"我会小心开的。保证。",
"Ich gebe das Zeichen. Mein erster Schuss.":"我发信号。我的第一枪。",
"Ich habe Verwundete hinter dem Tor. Lasst sie nicht durch!":"我门后还有伤员。别让他们冲过来！",
"Ich habe die Sitzordnung noch einmal geändert, Frau Kommissarin. Die Delegationen sitzen jetzt näher an der Allee. Wegen der Sonne.":"我又改了一次座位表，委员女士。代表团现在坐得离大道更近。因为太阳。",
"Ich habe dreißig Jahre auf diese Akten aufgepasst. Ich hätte nie gedacht, dass jemand dafür sein Leben riskiert.":"我守护这些档案三十年了。从没想过有人会为它们拼命。",
"Ich habe einen Fehler gefunden.":"我发现了一个错误。",
"Ich habe ihn. Danke, Falke.":"交给我。谢了，隼。",
"Ich habe ihn. Er bleibt bei mir im Wagen. Los jetzt!":"交给我。他跟我待在车里。快走！",
"Ich habe sie. Alle unverletzt. Geh, Falke.":"交给我。都没受伤。去吧，隼。",
"Ich höre ihre Frequenz mit. Alles verschlüsselt, alles kurz. Das ist nicht der normale Ostbund.":"我在监听他们的频率。全是加密的，全是短讯。这不是普通的东方联盟。",
"Ich kenne Kessar seit zwanzig Jahren. Er schießt nicht, solange er glaubt, noch reden zu können. Lassen Sie ihn nicht reden.":"我认识凯萨二十年了。只要他觉得还能说话，他就不会开枪。别让他说话。",
"Ich nehme die Westmauer, Weber die Ostecke. Falke, das Vorfeld gehört dir. Tief genug, dass du liegend nicht gesehen wirst.":"我守西墙，韦伯守东角。隼，前沿归你。挖到趴着不会被看见那么深。",
"Ich nehme die linke Seite, Weber die Rohrbrücke. Falke, du hältst die Mitte. Und setz dir Sandsäcke vor das Tor, solange noch Zeit ist.":"我守左边，韦伯守管廊。隼，你守中间。趁还有时间，在门前堆好沙袋。",
"Ich nehme jede Geisel, die ihr mir bringt. Und wenn einer von euch blutet, sagt es mir, bevor es zu spät ist.":"你们带来的每个人质我都接着。你们谁要是流血了，趁还来得及告诉我。",
"Ich saß seit der Ausbildung nicht mehr im Turm.":"训练之后我就没坐过炮塔了。",
"Ich schaue zu. Wer mir in drei Wochen den Rücken freihält, soll das hier im Schlaf können.":"我在旁边看着。三周后替我掩护后背的人，得闭着眼都能做好这些。",
"Ich sehe euch. Aber der Rauch zieht genau über die Landezone – haltet noch aus, ich suche eine Lücke.":"我看到你们了。但烟正好飘过着陆区——坚持住，我在找空隙。",
"Ich sehe sie. Mündungsfeuer im Trichterfeld. Noch eine Minute, vielleicht weniger.":"看到他们了。弹坑区有枪口焰。还有一分钟，也许更短。",
"Ich sichere.":"我警戒。",
"Ich wollte Panzer mit richtig vielen Details. Jetzt gibt es Panzer aus drei Epochen, nach echten Vorbildern gebaut: einen modernen Kampfpanzer, im Zweiten Weltkrieg einen mittleren und einen schweren Panzer, im Ersten Weltkrieg einen leichten Panzer mit dem ersten voll drehbaren Turm und einen schweren Sturmpanzer. Dazu Innenräume, einen Ladeschützen mit Armen und echtem Ladeablauf, Munition, die in jedem Panzer woanders liegt (im modernen hinter einer Schiebetür), ein Schadensmodell mit Besatzung und Munitionslager, Tarnungen zum Freispielen und eine neue Klasse: die Panzerbesatzung.":"我想要细节非常丰富的坦克。现在有了三个时代、参照真实原型打造的坦克：一辆现代主战坦克，二战时期的一辆中型和一辆重型坦克，一战时期一辆拥有首个全旋转炮塔的轻型坦克和一辆重型突击坦克。此外还有车内空间、有手臂并按真实流程装填的装填手、每辆坦克存放位置都不同的弹药（现代坦克里在一扇滑门后面）、包含乘员和弹药架的损伤模型、可解锁的迷彩，以及一个新兵种：坦克乘员。",
"Ideen wie Verletzungen mit Verband, zerstörbare Wände, verformbare Autos, Gräben zum Selbstgraben und Schüsse, die man je nach Kaliber unterschiedlich weit hört":"诸如需要包扎的伤势、可破坏的墙体、会变形的汽车、可自己挖掘的战壕，以及因口径不同而传播距离不同的枪声等创意",
"Ihr":"你们",
"Ihr ({0} {1}{2}) gegen {3} Bots.":"你们（{0} {1}{2}）对 {3} 个机器人。",
"Ihr habt gehalten. Jetzt brauchen wir Treibstoff und Granaten – die Kolonne aus Ostrau steckt fest.":"你们守住了。现在我们需要燃料和炮弹——来自奥斯特劳的车队被困住了。",
"Ihr verschwendet Verbandszeug. Ich werde nichts sagen, was ihr nicht schon wisst.":"你们在浪费绷带。我不会说任何你们不知道的事。",
"Ihr zwei seid alles, was zwischen ihnen und dem Tal steht. Haltet die Höhe – aber verheizt euch nicht.":"你们两个是挡在他们和河谷之间的全部力量。守住高地——但别白白送命。",
"Ihre Familie ist in Sicherheit, Herr Vogt. Anker hat sie heute Nachmittag abgeholt.":"你的家人安全了，福格特先生。锚点今天下午把他们接走了。",
"Im Anschlag an einer Kante/Brüstung oder im Liegen liegt die Waffe auf: kaum Schwanken, weniger Rückstoß. Sprinttaste im Anschlag: Atem anhalten.":"在边缘/胸墙处开镜或卧倒时武器有依托：几乎不晃、后坐力更小。开镜时按冲刺键：屏息。",
"Im Anschlag streut jede Waffe viel weniger.":"开镜时所有武器的散布都会小得多。",
