"Im Grenztal von Sant Aurel hält die Waffenruhe zwischen Nordkorps und Ostbund seit drei Wochen. Dann verstummt das Funkrelais, und Feldwebel Lenz und sein Trupp stoßen auf einen Plan, der beide Seiten zurück in den Krieg treiben soll.":"在圣奥雷尔的边境河谷，北方军团与东方联盟之间的停火已维持三周。随后无线电中继站陷入沉寂，伦茨上士和他的小队发现了一个要把双方重新拖入战争的计划。",
"Im Grenztal von Sant Aurel hält die Waffenruhe zwischen Nordkorps und Ostbund seit drei Wochen. Dann verstummt das Funkrelais, und Feldwebel Lenz und sein Trupp stoßen auf einen Plan, der beide Seiten zurück in den Krieg treiben soll. Akt I „Waffenruhe“, Akt II „Feuer im Tal“, Akt III „Phase zwei“.":"在圣奥雷尔边境河谷，北方军团与东方联盟之间的停火已持续三周。随后无线电中继站陷入沉默，伦茨上士和他的小队发现了一个企图让双方重燃战火的计划。第一幕“停火”，第二幕“河谷之火”，第三幕“第二阶段”。",
"Im Match erscheint „VR starten“ (unten in der Mitte bzw. im Pausenmenü). Lobby und Einstellungen bleiben am Bildschirm.":"对局中会出现“启动 VR”（底部中央或暂停菜单中）。大厅和设置仍在屏幕上。",
"Im Panzer-Modus sitzt du auf einem Platz. Wähle ihn und sieh, was du dort selbst tust.":"坦克模式中你坐在一个岗位上。选择它，看看你在那里要亲手做什么。",
"Im Pförtnerhaus sitzen noch zwei Arbeiter. Sie wollen nicht ohne ihre Familien gehen – bring sie zu den Lkw, Falke.":"门卫室里还有两名工人。他们不肯丢下家人离开——把他们带到卡车那儿，隼。",
