"Im Werk laufen die Pumpen für das ganze Tal. Dort arbeiten dreihundert Leute, viele mit ihren Familien.":"工厂里的水泵供应整个河谷。那里有三百人在工作，很多人拖家带口。",
"Im Übungsgelände fährst und schießt du jeden Panzer frei (Sitzwechsel im Fahrzeug). Für Simulation mit Handgriffen, Rolle und KI-Besatzung startet der Modus „Panzer“ auf dieser Karte: eigene Feuerstellung an der Panzerschießbahn, leichte Feindkräfte im Zielraum. Sonst: Lobby → Reiter „Panzer“.":"在训练场中你可以自由驾驶并射击任何坦克（可在车内换位）。如需带操作步骤、岗位和 AI 车组的模拟，会在这张地图上启动“坦克”模式：坦克射击场上有你自己的射击阵地，目标区有轻型敌军。否则请到：大厅 →“坦克”标签页。",
