"Infiziert und Waffenspiel gingen online, jede Klasse bekam eine eigene Fähigkeit, im Realismus-Modus muss man Munition bei Gefallenen aufsammeln, und Pioniere können Sandsäcke, MG-Nester und Bunker bauen. Die Waffen bekamen mehr Details. Dazu kam eine neue Karte: eine Zauberbibliothek in einer Steinhalle mit verwinkelten Regalgassen, Galerien und Brücken.":"“感染”和“军备竞赛”上线了，每个兵种都有了自己的技能，在写实模式中必须从阵亡者身上捡弹药，工兵可以搭建沙袋、机枪巢和碉堡。武器细节更丰富了。另外还有一张新地图：石厅里的魔法图书馆，有曲折的书架通道、回廊和桥。",
"Infizierte":"感染者",
