"Ist nicht so schlimm, wie es aussieht … Bring den Major hoch, Falke. Das ist wichtiger.":"没看上去那么严重……把少校送上去，隼。那更重要。",
"JK-9 Falke: Kampfjet mit Bordkanone, Raketen und Bomben. Auf dem Fliegerhorst startet er von der Bahn.":"JK-9 隼：配备机炮、导弹和炸弹的战斗机。在空军基地从跑道起飞。",
"Ja":"是",
"Ja, der Arm hängt in der Schlinge. Schießen kann ich mit der anderen Hand. Diskussion beendet.":"是，胳膊吊着绷带。我能用另一只手开枪。不用讨论了。",
