"Januar":"一月",
"Jaro Vahl lebend festnehmen":"活捉亚罗·瓦尔",
"Je 25 Abschüsse mit 10 verschiedenen Waffen.":"用 10 种不同武器各击杀 25 次。",
"Je nach Karte (Niemandsland: 1. Weltkrieg, sonst modern)":"取决于地图（无人区：一战，其他：现代）",
"Jede Klasse hat drei Ausführungen. Die Teamfarbe an Ärmel und Helm bleibt immer erkennbar.":"每个兵种有三种款式，袖子和头盔上的队伍颜色始终可辨。",
"Jede Waffe hat ihren eigenen Schnitt.":"每把武器都有自己的轮廓。",
"Jede Waffe ist hier frei – auch noch gesperrte zum Probeschießen. Reserve unbegrenzt.":"这里所有武器都可用——包括未解锁的，可试射。备弹无限。",
"Jede gehaltene Flagge: 1 Punkt alle 4 Sekunden":"每面守住的旗帜：每 4 秒 1 分",
"Jeder Abschuss befördert dich zur nächsten Waffe – von der MP über das Scharfschützengewehr bis zum Kampfmesser. Wer mit der letzten Stufe trifft, gewinnt. Ein Messerabschuss wirft das Opfer eine Stufe zurück.":"每次击杀都会升级到下一把武器——从冲锋枪到狙击步枪，最后是战术刀。在最后一级完成击杀者获胜。被刀杀者会降一级。",
"Jeder Abschuss bringt Munition für die Waffe, mit der er gelang: ein Magazin, beim Maschinengewehr 20 Schuss direkt in den Gurt. Der Vorrat wächst höchstens ein Magazin über den Startwert. Online entscheidet der Host.":"每次击杀都会为所用武器补充弹药：一个弹匣，机枪则直接往弹链加 20 发。备弹最多比初始多一个弹匣。联机时由房主决定。",
"Jeder Abschuss bringt ein Magazin (MG: 20 Schuss)":"每次击杀补一个弹匣（机枪：20 发）",
"Jeder Ausgeschaltete verliert seine Erkennungsmarke. Sammle die Marken der Gegner ein, um Abschüsse zu bestätigen – und schnapp dir die Marken deiner Kameraden, bevor der Gegner es tut. Wer nur aus der Ferne schießt, punktet nicht.":"每名被击倒者都会掉落狗牌。拾取敌方狗牌以确认击杀——并抢在敌人之前拾回队友的狗牌。只在远处射击是得不到分的。",
"Jeder Handgriff selbst, keine Außenansicht, KI-Besatzung auf den anderen Plätzen.":"每个操作都亲力亲为，没有外部视角，其他岗位由 AI 车组负责。",
"Jeder Handgriff selbst, keine Außenansicht.":"所有操作亲力亲为，无外部视角。",
