"Jet: Start von der Bahn, Luftkampf gegen Hubschrauber":"喷气机：跑道起飞，与直升机空战",
"Jet: W/S Schub, Maus neigen/rollen, A/D Seitenruder. Auf der Bahn Vollgas, ab etwa 250 km/h sanft ziehen.":"喷气机：W/S 推力，鼠标俯仰/横滚，A/D 方向舵。跑道上全油门，约 250 公里/时轻拉起飞。",
"Jetzt die zweite Stellung. Sie haben uns gehört – Verstärkung kommt!":"现在是第二处阵地。他们听到动静了——增援来了！",
