"KP-1 Mammut":"KP-1 Mammut",
"KP-1 Mammut: Kampfpanzer mit Wärmebild und Munitionsbunker, 4 Mann; zweiter Stellplatz: SZ-8 Igel (Schützenpanzer, 30 mm + Lenkflugkörper); dazu LP-21 Gämse (leicht, 105 mm) und Transporter RS-8 Waran (8×8, 30 mm), LKW-5, GMW-6, GW-7 (MG-Ring)":"KP-1 Mammut：配热成像与弹药隔舱的主战坦克，乘员 4 人；第二车位：SZ-8 Igel（步兵战车，30 毫米炮 + 导弹）；另有 LP-21 Gämse（轻型，105 毫米）以及运输车 RS-8 Waran（8×8，30 毫米）、LKW-5、GMW-6、GW-7（机枪环架）",
"KP-1 und SZ-8: Wärmebild und Restlicht. KP-68 (1960er) und Weltkriegspanzer: nur Optik und Winkelspiegel. Munition passt zur Kanone – KP-68: Treibspiegel, Hohlladung, Quetschkopf, Kanister; SZ-8: 30-mm-Feuerstöße und Lenkflugkörper. Leicht: LP-21 (105 mm, schnell, dünn gepanzert), LP-39 (37 mm). Schwer: SP-58 (120 mm, 1950er), SP-45 (lange 88 mm, 150-mm-Bug).":"KP-1 与 SZ-8：热成像与微光。KP-68（1960 年代）及世界大战坦克：仅有光学瞄具与潜望镜。弹药取决于火炮——KP-68：脱壳穿甲弹、破甲弹、碎甲弹、霰弹；SZ-8：30 毫米点射与导弹。轻型：LP-21（105 毫米，快速，装甲薄），LP-39（37 毫米）。重型：SP-58（120 毫米，1950 年代），SP-45（长身管 88 毫米，150 毫米车首）。",
"KP-68 Auerochs: Gussturm, 105 mm, Infrarot-Scheinwerfer, 4 Mann; zweiter Stellplatz SP-58 Mastodon (schwer, 120 mm); Transporter MTW-13 Kröte (Ketten, MG), LKW-5, GMW-6":"KP-68 Auerochs：铸造炮塔，105 毫米炮，红外探照灯，乘员 4 人；第二车位 SP-58 Mastodon（重型，120 毫米）；运输车 MTW-13 Kröte（履带，机枪）、LKW-5、GMW-6",
"KP-68 „Auerochs“ (nur Optik)":"KP-68“Auerochs”（仅光学瞄具）",
