"KV-47, VP-9, QX-90 und Adler nach echten Fotos neu gebaut, dazu ZW-12 Zwilling, P-9A und PS-41 Wirbel und der Modus Stellung. Aus Gräben klettert man jetzt heraus. In VR gibt es Hände, beidhändiges Halten, Holster an Rücken und Hüfte und echtes Gehen im Raum.":"KV-47、VP-9、QX-90 和 Adler 依照真实照片重新制作，另有 ZW-12 Zwilling、P-9A 和 PS-41 Wirbel，以及“据点”模式。现在可以从战壕里爬出来了。VR 中加入了双手、双手持枪、背部和腰部的枪套，以及真实的房间内行走。",
