"Kein Gamepad erkannt. Drück eine Taste am Controller.":"未检测到手柄。请按一下手柄上的按键。",
"Kein HUD, kein Fadenkreuz. Magazine zählen einzeln, halbleere bleiben halbleer. Du lädst durch, sicherst, behebst Ladehemmungen und stellst das Visier auf die Entfernung ein. Treffer verwunden einzelne Körperteile, Blutungen stillst du mit Verband oder Abbinden, und wer zu viel Blut verliert, wird bewusstlos.":"没有 HUD，没有准星。弹匣逐个计数，半空的弹匣始终是半空的。你要上膛、关保险、排除卡壳，并按距离调整表尺。命中会伤及具体身体部位，你需要用绷带或止血带止血，失血过多就会昏迷。",
