"Kein Raum mit diesem Code gefunden. Code prüfen – vielleicht ist der Raum schon geschlossen.":"找不到使用此代码的房间。请检查代码——房间可能已关闭。",
"Kein Rufzeichen, keine Uniform, keine Fahne. Die Leute dort nennen sich „Graue Kompanie“. Sie kämpfen für den, der zahlt.":"没有呼号，没有制服，没有旗帜。他们自称“灰色连队”。谁给钱就为谁打仗。",
