"Kerzenschein":"烛光",
"Kessar":"凯萨",
"Kessar greift mit allem an, was ihm folgt. Darens Brigade erhält den Befehl, mitzumarschieren – und verweigert ihn. Nordkorps- und Ostbund-Soldaten halten gemeinsam die Kapellenruine, holen das Artillerie-Funkgerät zurück und bergen die Verwundeten, bis Kessars Angriff zusammenbricht. Kessar zieht sich zurück und kündigt über Funk an, „die Wahrheit selbst zu senden“.":"凯萨率领所有追随者发起进攻。达伦的旅奉命随行——却拒绝了。北方军团和东方联盟的士兵共同守住小教堂废墟，夺回炮兵电台并救回伤员，直到凯萨的进攻瓦解。凯萨撤退，并通过无线电宣称要“亲自播出真相”。",
"Kessar greift mit allem an, was ihm folgt. Nimm mit Nordkorps- und Ostbund-Soldaten die Kapellenruine, halte sie gegen seine Wellen, hol das Artillerie-Funkgerät zurück und birg die Verwundeten.":"凯萨率领所有追随者进攻。与北方军团和东方联盟的士兵一起夺取小教堂废墟，顶住他一波波的进攻，夺回炮兵电台并救回伤员。",
"Kessar hat den Wald über dem Holzplatz angezündet. Flieg als Bordschütze in „Libelle 1“, räume die Flugabwehr ab, hol die Arbeiter heraus und zieh dich Linie um Linie vor Feuer und Feind zurück.":"凯萨点燃了木材场上方的森林。作为“蜻蜓 1 号”的机枪手出击，清除防空火力，救出工人，在大火和敌人面前一道防线一道防线地撤退。",
"Kessar hat ihn angezündet, um seinen Vormarsch zu decken. Auf dem Holzplatz sitzen Arbeiter mit ihren Familien fest.":"凯萨放火掩护他的推进。木材场里困着工人和他们的家人。",
"Kessar hat sich im Funkhaus von Veldmark verschanzt, mitten im dichten Stadtkern. Stockwerk für Stockwerk, durch Treppenhäuser und Wohnungen, an Zivilisten vorbei, stellt Falk ihn auf dem Dach. Kessar ergibt sich. Daren und Brandt verkünden über den Sender gemeinsam die Fortsetzung der Waffenruhe. Doch in Kessars Tasche steckt ein Notizbuch mit Zahlungen eines „Kranich“ – und auf der offenen Frequenz meldet sich eine fremde Stimme: „Kessar ist gescheitert. Phase zwei beginnt.“":"凯萨躲进了费尔德马克市中心密集街区里的广播大楼。法尔克一层一层，穿过楼梯间和公寓，绕过平民，终于在屋顶堵住了他。凯萨投降。达伦和勃兰特共同通过电台宣布停火继续。然而凯萨口袋里有一本记着“鹤”付款的笔记本——公开频道上传来一个陌生的声音：“凯萨失败了。第二阶段开始。”",
"Kessar hat sich im Funkhaus von Veldmark verschanzt. Bring die Menschen auf der Straße in Sicherheit, kämpf dich über den Platz und durch das Funkhaus – und nimm Kessar lebend fest.":"凯萨躲进了费尔德马克的广播大楼。把街上的人转移到安全地带，杀过广场、攻进广播大楼——活捉凯萨。",
"Kessar ist gescheitert. Das war vorhersehbar. Phase zwei beginnt.":"凯萨失败了。这在意料之中。第二阶段开始。",
"Kessar ist nicht der Ostbund. Er will einen Krieg, den keiner von uns will. Hier – seine Befehle, mit seiner Unterschrift.":"凯萨不代表东方联盟。他要的是一场我们谁都不想要的战争。给——他的命令，有他的签名。",
"Kessar ist unbewaffnet. Schalte die Leibwache aus und fordere ihn zur Aufgabe auf.":"凯萨没有武器。清掉保镖并命令他投降。",
"Kessar lebend festnehmen (Fehlschlag, wenn er fällt)":"活捉凯萨（他若死亡则任务失败）",
"Kessar nimmt alles mit, was er über seine Geldgeber hat. Wenn er abhebt, sehen wir es nie wieder.":"凯萨要带走他手里关于金主的一切。他一起飞，我们就再也见不到了。",
"Kessar setzt alles auf eine Karte. Nordkorps und Ostbund-Soldaten kämpfen Seite an Seite – doch hinter Kessar steht noch jemand.":"凯萨孤注一掷。北方军团与东方联盟的士兵并肩作战——但凯萨背后还另有其人。",
"Kessar spricht auf einer zweiten Frequenz mit jemandem. Verschlüsselt – aber nicht mit seinem eigenen Schlüssel.":"凯萨在第二个频率上和某人通话。加密的——但用的不是他自己的密钥。",
"Kessar will das Werk angreifen und dem Nordkorps die Schuld geben. Halte das Werkstor, bis die Familien der Werkssiedlung abtransportiert sind.":"凯萨想袭击工厂并嫁祸北方军团。守住厂门，直到工厂家属区的家庭全部撤离。",
"Kessar will die Brücke am Grenzfluss sprengen. Fahr den Kampfpanzer „Eisen 2“, decke die Infanterie im Dorf und halte die Brücke für die Pioniere.":"凯萨要炸毁边境河上的桥。驾驶主战坦克“铁 2 号”，掩护村中的步兵，为工兵守住桥。",
"Kessar will mit den Unterlagen seiner Geldgeber außer Landes fliegen. Bring Libelle 1 in die Landezone, sprenge die Flugabwehr, durchkämme die Hallen und stoppe seine Maschine, bevor sie abhebt.":"凯萨想带着金主的文件飞出国境。把蜻蜓 1 号开到着陆区，炸掉防空火力，搜索厂房，在他的飞机起飞前拦住它。",
"Kessar will mit den Unterlagen seiner Geldgeber außer Landes fliegen. Der Trupp – Lenz wieder dabei, Arm in der Schlinge – landet mit „Libelle 1“ am Rand des Fliegerhorsts Hagenmoor. Flugabwehr ausschalten, durch die Hangars vorstoßen, die Transportmaschine auf der Startbahn stoppen. Kessar entkommt im letzten Moment mit einem Wagen in die Stadt Veldmark.":"凯萨想带着金主的文件飞出国境。小队——伦茨也归队了，手臂还吊着绷带——乘“蜻蜓 1 号”在哈根莫尔空军基地边缘着陆。摧毁防空火力，穿过机库，在跑道上拦下运输机。最后一刻，凯萨驾车逃往费尔德马克市。",
"Kessar will über das Relais von Sant Aurel gefälschte Angriffsbefehle senden. Führ den Trupp selbst durch die Altstadt, schütz die Einwohner in der Kirche und schalte den Sender ab, bevor der Countdown endet.":"凯萨想通过圣奥雷尔中继站发送伪造的进攻命令。亲自带队穿过老城，保护教堂里的居民，在倒计时结束前关闭发射机。",
"Kessar wird festgenommen":"正在逮捕凯萨",
"Kessar wurde getroffen. Ohne seine Aussage bleibt die Wahrheit im Dunkeln – wir brauchen ihn lebend.":"凯萨被击中了。没有他的证词真相就无从得知——我们要活的。",
"Kessars Botschaft ist hinausgegangen – beide Seiten greifen zu den Waffen.":"凯萨的消息发出去了——双方都拿起了武器。",
"Kessars Leute haben das Funkhaus zurückerobert.":"凯萨的人夺回了广播大楼。",
"Kessars Leute haben die Kirche gestürmt.":"凯萨的人冲进了教堂。",
"Kessars Leute halten das Wrack! Weber, bleib hinter mir!":"凯萨的人守着残骸！韦伯，跟在我后面！",
"Kessars Leute halten die Archivare im Staatsarchiv fest und wollen die Originale der Waffenruhe vernichten – die einzigen Papiere, die seine Fälschungen widerlegen. Falk klärt erst auf, markiert die Wachen, dann geht der Trupp Raum für Raum vor. Keine Geisel darf zu Schaden kommen. Am Ende brennt der Ostflügel, und über dem Tal steigt Rauch auf: Kessar hat den Brandwald angezündet.":"凯萨的人把档案员扣押在国家档案馆，企图销毁停火协议原件——那是唯一能揭穿他伪造文件的证据。法尔克先行侦察并标记守卫，随后小队逐屋推进。不能让任何人质受到伤害。最后东翼起火，河谷上空浓烟升起：凯萨点燃了森林。",
"Kessars Leute halten die Archivare im Staatsarchiv fest und wollen die Originale der Waffenruhe vernichten. Kläre von der Galerie auf, gib das Zeichen zum Zugriff – und triff keine Geisel.":"凯萨的人把档案员扣在国家档案馆，想销毁停火协议原件。从回廊侦察，发出突击信号——不能打中任何人质。",
"Kessars Leute kommen von Süden durch die Walzhalle und über den Westhof. Wir halten das Werkstor.":"凯萨的人从南面穿过轧钢厂房、经西院过来。我们守住厂门。",
"Kessars Maschine ist gestartet – mit ihr alle Beweise.":"凯萨的飞机起飞了——所有证据也随之而去。",
