"Klare Linien, kühle Morgenluft und viel Platz: In der Mitte die Trainingsanlage mit acht Bahnen, Klappzielen auf 10 bis 100 Metern und dem Einschieß-Parcours – drumherum ein 2,6 × 2,6 km großes Übungsgelände. Im Fahrzeughof steht jedes Muster zum Einsteigen bereit, vom Sturmpanzer bis zum Kastenwagen. Die Fahrstrecke prüft Slalom, Rampe, Seitenneigung, Steigungen, Graben, Panzergraben und Furt; auf der Panzerschießbahn warten Scheiben, Pappkameraden, Ziel-Panzer und Schienenziele auf 200 bis 2500 Metern mit Trefferanzeige. Am Flugfeld starten Jets von der 1200-m-Bahn und Hubschrauber von drei Landeplätzen – über dem Zielgebiet schweben Ballons und kreisen Zieldrohnen. Teleport-Tafeln und das Übungsmenü bringen dich überall hin.":"线条简洁，清晨空气凉爽，空间宽广：中央是设有八条靶道、10 至 100 米翻板靶和校枪障碍赛的训练设施——周围是 2.6 × 2.6 公里的训练场。载具场里每种车型都可乘坐，从突击坦克到厢式货车。驾驶赛道考验绕桩、坡道、侧倾、上坡、壕沟、反坦克壕和涉水；坦克射击场在 200 至 2500 米处设有靶板、纸板人像、靶标坦克和轨道靶，并显示命中。机场上喷气机从 1200 米跑道起飞，直升机从三个停机坪起飞——目标区上空飘着气球，靶机在盘旋。传送牌和训练菜单可带你到任何地方。",
