"Klassen-Fähigkeiten, Bauen, MG-Stellungen, Türen und Tore, Durchschüsse und die steuerbare FPV-Drohne als Abschussserie.":"兵种技能、建造、机枪阵地、门与大门、穿透射击，以及作为连杀奖励的可操控 FPV 无人机。",
