"Licht":"车灯",
"Licht und Farben wurden an einem echten Video gemessen und nachgestellt: Pflaster, Dächer, Putz, Wellblech und Ziegel in diesem Stil, ein bewölkter Himmel als Standard, ein dichteres Dorf im Grenzland mit zehn eingerichteten Häusern und begehbare Hallen im Hafen. Die Soldaten bekamen Splittertarn, große Helme und Rucksäcke. Dazu die ersten Zivilfahrzeuge zum Selbstfahren: Limousine, Kastenwagen, Gabelstapler und Sattelzug.":"光照和色彩依照一段真实视频测量并还原：这种风格的路面、屋顶、灰泥、波纹铁皮和砖块，默认阴天，“边境地带”里更密集的村庄，有十座布置好的房屋，以及“港口”里可进入的厂房。士兵们换上了碎片迷彩、大头盔和背包。此外还有第一批可以自己驾驶的民用车辆：轿车、厢式货车、叉车和半挂卡车。",
