"Maschinenpistole":"冲锋枪",
"Maschinenpistole der Weltkriegszeit aus Stahlrohr und Bakelit: gemächlicher Takt, gutmütig im Dauerfeuer, zweiunddreißig Schuss im Stangenmagazin. Der Magazinschacht ist zugleich der Vordergriff.":"世界大战时期的冲锋枪，钢管和胶木制成：射速从容，连射温和，直弹匣三十二发。弹匣井兼作前握把。",
"Maschinenpistole mit eingebautem Schalldämpfer über die ganze Lauflänge: kein Mündungsfeuer, kaum ein Knall – nur das Klacken des Verschlusses. Leise ist sie nicht wehrlos, aber auf Distanz verliert sie schnell an Wucht.":"整根枪管内置消音器的冲锋枪：无枪口焰，几乎无枪声——只有枪机的咔嗒声。安静不等于无害，但远距离威力衰减很快。",
