"Mehrspieler: Browser-, Handy- und VR-Spieler sind in denselben Räumen, wenn alle dieselbe Spielfassung haben. Einladungslinks aus der App führen auf die Webseite.":"多人模式：只要版本相同，浏览器、手机和 VR 玩家可在同一房间。应用中的邀请链接会指向网站。",
"Mehrstöckiger Häuserkampf":"多层建筑巷战",
"Mehrzweck":"多地形",
"Mehrzweckgranate":"多用途弹",
"Meilensteine":"里程碑",
"Mein Befehl lautete, heute Morgen mit Kessar zu marschieren. Ich habe ihn verweigert. Zweihundert meiner Leute auch.":"我接到的命令是今早随凯萨进军。我拒绝了。我的两百名部下也拒绝了。",
"Mein Bein trägt mich noch nicht in ein Cockpit. Aber auf der Bahn steht ein JK-9, vollgetankt. Falke, du hattest zwölf Stunden im Simulator in Hohenfeld.":"我这条腿还爬不进驾驶舱。但跑道上有架加满油的 JK-9。隼，你在霍恩费尔德上过十二小时模拟器。",
"Mein Großvater Emil war zweiundzwanzig. Sein Panzer hieß Bison, und sein Zielfernrohr war alles, was er hatte.":"我祖父埃米尔那年二十二岁。他的坦克叫“Bison”，瞄准镜就是他的全部。",
"Mein Großvater hat einmal gesagt: An der Furt von Mirenfurt entscheidet sich jeder Krieg in diesem Tal. Er war dabei – vor achtzig Jahren.":"我祖父曾说过：这条河谷里的每一场战争，都在米伦富特渡口决出胜负。他当年就在那里——八十年前。",
"Mein Ziel war von Anfang an: so realistisch wie möglich, irgendwo zwischen CS:GO, Battlefield und Bodycam. An diesem Tag kamen der Hafen und das Werk dazu, Bots, die Deckung suchen und flankieren, Fotoscan-Texturen und echte Tonaufnahmen für die Waffen. Weil ich auch Fahrzeuge wollte, entstand die große Karte Grenzland mit Dorf, Bauernhof, Industrie und einer Brücke, samt ein paar versteckten Geheimnissen.":"我从一开始的目标就是：尽可能真实，介于 CS:GO、Battlefield 和 Bodycam 之间。这一天加入了“港口”和“工厂”，会寻找掩体和包抄的机器人，照片扫描纹理以及真实录制的武器音效。因为我也想要载具，于是诞生了大地图“边境地带”，有村庄、农场、工业区和一座桥，还藏着几个秘密。",
"Meine Brigade hält die Straße nach Osten. Aber die Graue Kompanie kommt nicht über Straßen. Sie kommt durch die Trichter.":"我的旅守着往东的路。但灰色连队不走公路。他们从弹坑里过来。",
"Meine Freunde testen.":"朋友们来测试。",
"Meine Laufbahn ist mir weniger wert als die Menschen in diesem Tal.":"对我来说，前程比不上这河谷里的百姓。",
"Meine Leute haben heute gegen Männer gekämpft, mit denen sie gestern noch gegessen haben. Das vergessen sie nicht.":"我的人今天和昨天还一起吃饭的人打了仗。他们不会忘记。",
"Meine Leute? Ilja, du verstehst es immer noch nicht. Ich war nie derjenige, der bezahlt hat.":"我的人？伊利亚，你还是不明白。我从来都不是出钱的那个。",
