"Muss man sich vor KI fürchten? Ich finde nicht. Mit Respekt sollte man ihr aber begegnen: Sie entwickelt sich rasant, und es lohnt sich, wachsam zu bleiben, wohin die Reise in den kommenden Jahren geht. Das ändert nichts daran, dass wir heute leben, und heute kann KI genau die Lücken füllen, die man selbst hat. Bei mir war das das Programmieren.":"我们需要害怕 AI 吗？我觉得不必。但应当以尊重的态度对待它：它发展得极快，值得保持警惕，看看未来几年会走向何方。这并不改变我们活在当下的事实，而当下，AI 恰好能填补我们自身的短板。对我来说，那就是编程。",
