"Nur für Spieler der ersten Stunde. Bis zu drei eigene Muster – danach in der Tarnungsauswahl jeder Waffe. Online sehen die anderen dein Muster.":"仅限首发玩家。最多三个自定义图案——之后可在每把武器的迷彩选择中使用。联机时其他人能看到你的图案。",
