"Nur für Spieler der ersten Stunde: Pistole mit goldenem Kompensator. Etwas mehr Wucht und weniger Rückstoß als die P-9, dafür ein Schuss weniger im Magazin.":"首发玩家专属：带金色补偿器的手枪。比 P-9 稍猛、后坐力更小，但弹匣少一发。",
