"Nur wenn du einen Raum öffnest oder beitrittst, verlassen Daten das Gerät; NULLPUNKT selbst speichert davon nichts. Den Verbindungsaufbau vermitteln öffentliche Nostr-Relays (verschlüsselt, ohne Konto), STUN-Server von Google und Cloudflare helfen beim Finden der Verbindung. Danach spielen die Browser direkt miteinander (WebRTC) – dabei sehen die Mitspieler im Raum technisch deine IP-Adresse. Sichtbar sind außerdem dein Spielername, Team, Stufe und Gerät. Öffentliche Spiele stehen mit Raumcode, Name des Hosts und Karte in einer öffentlichen Liste. Einen eigenen Spielserver gibt es nicht.":"只有在你创建或加入房间时，数据才会离开你的设备；NULLPUNKT 本身不保存其中任何内容。连接由公共 Nostr 中继（加密，无需账号）进行撮合，Google 和 Cloudflare 的 STUN 服务器帮助建立连接。之后浏览器之间直接游玩（WebRTC）——房间里的其他玩家在技术上可以看到你的 IP 地址。你的玩家名、队伍、等级和设备也是可见的。公开游戏会连同房间码、房主名称和地图显示在公开列表中。没有专用游戏服务器。",
