"Panzerabwehr-Rohr der Pioniere: Raketengranate mit Hohlladung. Knackt Geländewagen mit einem Treffer in die Flanke, Kampfpanzer mit zweien ins Heck – und räumt jede Stellung.":"工兵的反坦克火箭筒：破甲火箭弹。侧面一发击毁越野车，尾部两发击毁主战坦克——还能清除任何阵地。",
