"Panzerbesatzung: leichte Weste, MP und Pistole, Rauch- und Splittergranate, Fernglas; wechselt im Panzer doppelt so schnell den Sitz, lädt 25 % schneller und repariert das eigene Fahrzeug im Notfall.":"坦克乘员：轻型背心、冲锋枪和手枪、烟雾弹和破片手雷、望远镜；在坦克内换座快一倍，装填快 25%，紧急时可维修己方载具。",
