"Panzersimulation: Du übernimmst einen Platz – Fahrer, Richtschütze, Ladeschütze oder Kommandant – die KI-Besatzung den Rest. Motor anlassen, Gang einlegen, Waffe scharf schalten, laden und entsichern, Ziele ansprechen: in der Simulation machst du jeden Handgriff selbst. Wucht, Hohlladung, Spreng und Kanister wirken je nach Panzerung und Auftreffwinkel. Im Arcade-Stil fährst und schießt du allein.":"坦克模拟：你担任一个岗位——驾驶员、炮手、装填手或车长——其余由 AI 乘员负责。启动引擎、挂挡、武器上电、装填并解除保险、指示目标：模拟模式下每个动作都由你亲手完成。穿甲弹、破甲弹、榴弹和霰弹的效果取决于装甲和入射角。街机风格下你独自驾驶和射击。",
