"Programmieren ist dabei nur ein Einsatzgebiet. KI kann zum Beispiel auch Musik erzeugen, das sehe ich allerdings kritischer, denn Musik ist für mich echte Kunst. Programmieren ist für mich eher Handwerk: Hobby, Leidenschaft und eine Frage des Könnens. Weil mir genau dieses Können fehlt, habe ich mir Claude an die Seite geholt.":"编程只是其中一个应用领域。比如 AI 也能创作音乐，不过对此我持更审慎的态度，因为对我来说音乐是真正的艺术。而编程对我来说更像一门手艺：是爱好、是热情，也是能力的问题。正因为我缺少这种能力，我才请来了 Claude。",
