"Sie glauben, Sie hätten gewonnen, Unteroffizier. Sie haben einen einzigen Mann verhaftet.":"你以为你赢了，上士。你只是抓了一个人。",
"Sie haben Söldner bezahlt, damit sie eine Waffenruhe brechen. Damit Sie wieder liefern können. Das ist sehr wohl Ihre Sache.":"你花钱雇雇佣兵破坏停火，好让你能继续供货。这当然关你的事。",
"Sie haben es getan, damit andere morgen nicht kämpfen müssen. Auch das wird man nicht vergessen.":"他们这么做，是为了让别人明天不必再打仗。这一点也不会被忘记。",
"Sie haben gesagt, meiner Frau und den Kindern geschieht nichts, solange ich fahre und schweige.":"他们说只要我开船、闭嘴，我老婆孩子就不会有事。",
"Sie haben uns die Wahrheit aufbewahrt. Das ist mehr wert, als Sie denken.":"是你替我们保存了真相。这比你想的更有价值。",
"Sie haben uns gewarnt, Major. Warum?":"你提醒了我们，少校。为什么？",
