"Sie halten den Platz! Bleib an den Säulen, nicht über die offene Fläche!":"他们控制着广场！贴着柱子走，别穿越空地！",
"Sie kamen über die Furt. Nicht alle. Emil hat den Namen jedes Einzelnen bis zu seinem letzten Tag gewusst.":"他们渡过了渡口。不是所有人。埃米尔直到生命的最后一天都记得每一个人的名字。",
"Sie kommen auf die Kirche zu! Von Norden und Süden!":"他们朝教堂过来了！南北两面！",
"Sie kommen durch die Seitengänge! Und der Ostflügel brennt!":"他们从侧廊过来了！东翼也着火了！",
"Sie kommen hinter dem Rauch hervor! Von Norden!":"他们从烟里冲出来了！北面！",
"Sie sind am Tor! Zurück in die Stellung!":"他们到门口了！回到阵地！",
"Sie sind an der Kirchentür! Falke!":"他们到教堂门口了！隼！",
