"Sie sind in der Ruine! Zurück in die Mauern!":"他们进废墟了！回到墙后！",
"Sie sitzen in der Ruine! Wir gehen links herum!":"他们在废墟里！我们从左边绕过去！",
"Sie verhaften einen Geschäftsmann, Feldwebel. Ich habe Ware geliefert. Was die Leute damit machen, ist nicht meine Sache.":"你逮捕的是个商人，上士。我只是供货。别人拿货去做什么，不关我的事。",
