"Teste jede Waffe in Ruhe: Klappziele auf verschiedenen Distanzen, unbegrenzte Reservemunition und eine Trefferstatistik, die nicht lügt. Rund um den Stand liegt das Übungsgelände: alle Panzer, Transporter, Autos, Hubschrauber und Jets zum Einsteigen, eine Fahrstrecke, die Panzerschießbahn bis 2500 m mit Trefferanzeige und ein Flugfeld mit Luft- und Bodenzielen – allein, ohne Gegner.":"静心测试每把武器：不同距离的翻板靶、无限备弹和真实可信的命中统计。靶场周围是训练场：所有坦克、运输车、汽车、直升机和喷气机都可乘坐，还有驾驶赛道、带命中显示的 2500 米坦克射击场，以及设有空中和地面目标的机场——独自一人，没有敌人。",
