"Tipp: Blutungen stillst du mit Verband oder Abbinden, bevor das Bild grau wird.":"提示：在画面变灰之前，用绷带或止血带止血。",
"Tipp: Controller? Steuerkreuz wählt, A bestätigt, B geht zurück.":"提示：用手柄？十字键选择，A 确认，B 返回。",
"Tipp: Das Übungsgelände hat jedes Fahrzeug zum Einsteigen – ohne Gegner.":"提示：训练场里每种载具都能上去开——没有敌人。",
"Tipp: Dauerfeuer frisst sich durch dünne Wände. Deckung ist nicht gleich Schutz.":"提示：持续射击能打穿薄墙。隐蔽不等于掩护。",
"Tipp: Fünf Schuss auf den Punkt im Hauptmenü schießen die Waffe ein.":"提示：在主菜单向圆点打五发子弹即可完成归零校准。",
"Tipp: Gehockt und still stehend streut jede Waffe am wenigsten.":"提示：蹲下并保持静止时，任何武器的散布都最小。",
"Tipp: Grafik ruckelt? Unter Einstellungen eine Stufe niedriger wählen.":"提示：画面卡顿？在设置中调低一档。",
"Tipp: Halbleere Magazine bleiben in der Simulation halbleer. Zähl mit.":"提示：模拟模式中半空的弹匣始终是半空的。记好数。",
"Tipp: Im Panzer sagt der Kommandant das Ziel an – Richtschütze, Panzer, halbrechts, 800, Feuer.":"提示：在坦克里由车长报出目标——炮手，坦克，右前方，800，开火。",
