"Unberührbar":"不可触碰",
"Und Hauptmann Elias Brandt, Nordkorps. Die Waffenruhe gilt – für beide Seiten, ab sofort und ohne Ausnahme. Niemand schießt, der nicht muss.":"以及北方军团的埃利亚斯·勃兰特上尉。停火有效——对双方立即生效，没有例外。不到万不得已，谁都不许开枪。",
"Und achtet auf die Trupps mit Panzerfäusten. Die kommen leise durchs hohe Gras.":"还要注意带火箭筒的小组。他们会悄悄穿过高草摸过来。",
"Und auf dem Vorfeld wird ein Hubschrauber betankt. Zivil lackiert, aber mit Zusatztanks. Weit genug für jedes Land, das keine Fragen stellt.":"停机坪上还有架直升机在加油。民用涂装，但加装了副油箱。航程够飞到任何不问问题的国家。",
"Und danke an dich fürs Spielen. Über dein Feedback freue ich mich.":"也感谢你来玩。期待你的反馈。",
"Und der Kapitän? Anselm Vogt. Sie halten ihn im Kaibüro fest. Seine Familie haben sie bedroht, damit er fährt.":"那船长呢？安塞尔姆·福格特。他们把他扣在码头办公室。他们拿他的家人威胁他出航。",
"Und der dritte?":"那第三个呢？",
"Und die Brigade von Major Daren hat Befehl, mitzumarschieren.":"达伦少校的旅也接到命令随他进军。",
"Und diesmal kommen wir alle heim.":"这一次，我们都会回家。",
"Und niemand schießt, der nicht muss. Wir sind nicht wie Kessar.":"不到万不得已谁都不许开枪。我们和凯萨不一样。",
"Und schießt nicht in die Kirche. Da drin sitzen noch Leute aus der Stadt.":"还有，别朝教堂开火。里面还有镇上的居民。",
"Und warum sollten wir Ihnen trauen?":"我们凭什么相信你？",
"Und wenn es losgeht: Die Geiseln sitzen mitten zwischen ihnen. Jeder Schuss muss sitzen.":"动手时要注意：人质就坐在他们中间。每一枪都必须打准。",
"Und wenn sie wirklich unsere Uniformen tragen?":"要是他们真穿着我们的制服呢？",
"Und wer sind die beiden Stimmen? Die eine bin ich. Die andere ist eine KI. NULLPUNKT ist nämlich auch ein kleines Experiment.":"那两个声音是谁？一个是我，另一个是 AI。因为 NULLPUNKT 也是一个小小的实验。",
