"Universal-MG der Weltkriegszeit mit gelochtem Laufmantel und Gurttrommel: über tausend Schuss pro Minute, das Geräusch eines reißenden Tuchs. Wer ihn nicht festhält, schießt in den Himmel.":"世界大战时期的通用机枪，带开孔枪管护套和弹链鼓：射速每分钟超过千发，声如撕布。握不住就会打上天。",
"Unser Beobachtungsposten am Panzerwrack ist in der Nacht überrannt worden. Mit ihm das Artillerie-Funkgerät.":"我们在坦克残骸旁的观察哨昨夜被攻破了。连同炮兵电台一起。",
"Unser Turmantrieb muss in die Werkstatt. Aber in der Reserve steht noch der alte Auerochs. Der hat schon meinen Vater gefahren.":"我们的炮塔驱动得进修理厂。不过预备队里还有那辆老“Auerochs”。我父亲当年就开过它。",
"Unsere Frauen sind im ersten Lkw? Dann gehen wir. Danke.":"我们的妻子在第一辆卡车上？那我们走。谢谢。",
