"Zehn Freunde gleichzeitig in einem Match, und alles hat gehalten: ein voller Erfolg. Danach ging es direkt weiter: Verletzungen mit Verband und Wiederbeleben, neue Nahkampfwaffen wie Axt und Schlagstock, Fassaden, die nach Explosionen herausbrechen, Autos, die sich verformen, Fenster zum Zerschießen, über 20 Waffenaufsätze und die Stellungskriegskarte Niemandsland mit Gräben, die man mit dem Spaten selbst tiefer graben kann.":"十个朋友同时在一局里，一切都撑住了：大获成功。之后马不停蹄：可包扎和救起的伤势，斧头和警棍等新近战武器，爆炸后会崩塌的外墙，会变形的汽车，可以打碎的窗户，二十多种武器配件，以及阵地战地图“无人区”，里面的战壕可以用铁锹自己挖深。",
