"Zum ersten Mal habe ich das Spiel Freunden gezeigt. Zurück kam eine lange Fehlerliste: eine unsichtbare Wand an einer Treppe, schwebende Lampen und eine Waffe, die an Wänden nach oben klappt. Alles wurde abgearbeitet. Die Karten wurden um ein Viertel größer und bekamen mehr Deckung, die Bots lernen seitdem von den Spielern und kämpfen bis zu 32 gegen 32. Ich wollte Grafik wie in der Unreal Engine 5. Die KI hat mir ehrlich gesagt, dass das im Browser so nicht geht, und dann herausgeholt, was möglich ist.":"我第一次把游戏给朋友们看。反馈回来一长串错误清单：楼梯上有一堵看不见的墙、悬空的灯，还有一把贴墙就往上翻的枪。所有问题都逐一解决了。地图扩大了四分之一，掩体也更多了，机器人从此会向玩家学习，最多可以 32 对 32 作战。我想要虚幻引擎 5 那样的画面。AI 坦率地告诉我在浏览器里做不到，然后尽可能做到了最好。",
"Zur Galerie":"前往图库",
"Zur Markierung":"前往标记",
"Zur Website":"前往网站",
"Zureden":"正在劝说",
"Zurück":"返回",
"Zurück auf die Höhe! Die Stellung darf nicht fallen.":"回到高地上！阵地绝不能丢。",
"Zurück in Sant Aurel, diesmal am Abend und unter Zeitdruck: Kessar will über das Relais im Glockenturm gefälschte Angriffsbefehle an alle Einheiten senden. Lenz liegt im Lazarett – Falk führt den Trupp zum ersten Mal selbst. Die Einwohner suchen Schutz in der Kirche am Brunnenplatz. Das Relais wird rechtzeitig abgeschaltet; ein gefangener Funker verrät, dass Kessar zum Fliegerhorst Hagenmoor flieht.":"回到圣奥雷尔，这次是傍晚，时间紧迫：凯萨企图通过钟楼中继站向所有部队发送伪造的进攻命令。伦茨躺在野战医院——法尔克第一次独自带队。居民在喷泉广场的教堂里避难。中继站及时被关闭；被俘的通信兵供出凯萨正逃往哈根莫尔空军基地。",
"Zurück in den Raum":"返回房间",
"Zurück zum Gewehr":"换回步枪",
"Zurück zum Sammelpunkt":"返回集结点",
"Zurück zur Kapelle. Da draußen liegen noch Verwundete.":"回小教堂。外面还有伤员。",
"Zurück zur Website":"返回网站",
"Zurückgesetzt. Extrem nutzt wieder 8K-Schatten, wo die Grafikkarte es kann.":"已重置。显卡支持时，“极致”画质会重新使用 8K 阴影。",
