"Zusätzliche Knöpfe (Lehnen, Zielen + Feuern), Lage, Größe und Deckkraft jedes Knopfs: Touch-Layout-Editor.":"额外按键（侧身、瞄准+开火），每个按键的位置、大小和不透明度：触屏布局编辑器。",
"Zwei Abschüsse innerhalb von vier Sekunden.":"四秒内两次击杀。",
"Zwei Begleithubschrauber abschießen":"击落两架护航直升机",
"Zwei Gegner mit einer einzigen Kugel.":"一颗子弹击杀两名敌人。",
"Zwei Geländewagen mit schweren MGs! Sie wollen durchbrechen!":"两辆装重机枪的越野车！他们想突破！",
"Zwei Holzbrücken quer über die Halle":"两座横跨大厅的木桥",
"Zwei Kampfpanzer ausschalten":"击毁两辆主战坦克",
"Zwei Kranich sind bekannt. Einer fehlt.":"已知两只“鹤”。还差一只。",
"Zwei Nächte nach Kessars Festnahme hat Weber die fremde Stimme angepeilt: Sie sendet vom Funkhügel im Grenzland. Mit Nachtsichtgeräten schleicht der Trupp vom Gehöft über die Furt, schaltet Streifen lautlos aus und stürmt den Bunker der „Grauen Kompanie“ – Söldner ohne Hoheitszeichen. Ihr Anführer Jaro Vahl entkommt, aber Webers Kopie des Funkrechners verrät Phase zwei: einen Anschlag auf die öffentliche Sitzung der Kommission in Veldmark.":"凯萨被捕两夜后，韦伯测出了那个陌生声音的方位：它来自边境地带的电台山。小队戴着夜视仪从农庄出发，涉过浅滩，悄无声息地解决巡逻队，突袭“灰色连队”——一群没有标识的雇佣兵——的地堡。他们的头目亚罗·瓦尔逃走了，但韦伯拷贝的无线电电脑揭示了第二阶段：袭击委员会在费尔德马克的公开会议。",
"Zwei Panzer jenseits der Brücke! Panzergranate laden – und in Bewegung bleiben!":"桥那边有两辆坦克！装穿甲弹——保持移动！",
"Zwei Panzer, Zwölf Uhr, auf der Straße. Wir schießen zuerst.":"两辆坦克，十二点方向，路上。我们先开火。",
"Zwei Patronen im Lager – Doppelzuführung!":"膛内两发——双进弹！",
"Zwei Streifen am Feldweg, eine an der Furt. Du kannst sie umgehen – oder leise abräumen. Deine Entscheidung.":"田间小路上两支巡逻队，浅滩一支。你可以绕过去——或者悄悄清掉。你决定。",
"Zwei Teams, eine Rechnung: Jeder Abschuss zählt, jeder Tod kostet. Schnelle Wiedereinstiege halten das Tempo hoch – Flanken, Deckung und Serienprämien entscheiden das Match.":"两支队伍，一笔账：每次击杀都算数，每次死亡都有代价。快速复活保持高节奏——侧翼、掩体和连杀奖励决定胜负。",
"Zwei Teams, nur Messer: keine Schusswaffen, keine Granaten, keine Serienprämien. Wer schneller um die Ecke ist, gewinnt das Duell – Flanken und Überraschung entscheiden.":"两队只用刀：没有枪械、手雷和连杀奖励。谁先绕过拐角谁就赢——侧翼和突袭决定胜负。",
"Zwei Transporter verloren – die Kolonne kann nicht weiter.":"损失两辆运输车——车队无法继续前进。",
"Zwei Weichkern-Platten. Kaum spürbar, fängt eine kurze Salve ab.":"两块软质插板。几乎感觉不到，能挡住一个短点射。",
"Zwei auf einen Streich":"一石二鸟",
"Zwei kommen die Marktgasse herunter! Familie runter, Falke vorn!":"市场巷下来两个！一家人趴下，隼顶上去！",
"Zwei leichte MGs halten Gegner nieder, Schützen und ein Sanitäter sichern.":"两挺轻机枪压制敌人，步枪手和医疗兵负责掩护。",
"Zwei neue Großkarten, Flugplatz und Stadtkern, Relief auf allen großen Karten und viel Kleinkram auf den Straßen. 82 Materialien sind echte Fotoscans von Poly Haven (frei, CC0), auf Ultra in doppelter Auflösung.":"两张新的大地图“机场”和“市中心”，所有大地图都有地形起伏，街道上多了许多细节。82 种材质是来自 Poly Haven 的真实照片扫描（免费，CC0），超高画质下分辨率翻倍。",
"Zwei von drei. Der letzte steht am Westrand, fast am Kai.":"三个里有两个了。最后一个在西边缘，快到码头边了。",
"Zweibein":"两脚架",
"Zweimal kurz drücken: Verschluss ein Stück zurück – liegt eine Patrone im Lager? Ohne Patrone im Lager klickt es beim Abziehen nur.":"快速按两下：枪机稍向后拉——膛内有子弹吗？没有的话扣扳机只会咔嗒一声。",
"Zweite Gruppe von Süden! Sie wollen die Kirche als Deckung!":"南面第二组！他们想拿教堂当掩体！",
"Zweite Stimme":"第二个声音",
"Zweite Taste bei gehaltener erster = Kombination (z. B. LT + L3). Menü-Taste bricht ab.":"按住第一个键再按第二个键 = 组合键（如 LT + L3）。菜单键取消。",
"Zweite Welle":"第二波",
"Zweite Welle abwehren (Panzer und Schützenpanzer)":"击退第二波（坦克和步兵战车）",
"Zweiter":"第二",
"Zweiter Feuerknopf für den linken Daumen.":"供左手拇指使用的第二开火键。",
"Zweiter Lkw ist raus. Der letzte wird beladen – haltet durch.":"第二辆卡车出去了。最后一辆正在装人——坚持住。",
"Zweiter: dunkle Jacke, helles Hemd, bei der Treppe zur U-Bahn. Er zählt die Ausgänge.":"第二个：深色夹克、浅色衬衫，在地铁楼梯旁。他在数出口。",
"Zweitwaffe":"副武器",
"Zweitwaffe für Notfälle: blitzschnell gezogen, leicht geführt.":"应急副武器：拔枪极快，操控轻便。",
"Zwing Seyfried mit dichten Überflügen zur Landung (unter 150 m)":"以近距离通场逼迫赛弗里德降落（低于 150 米）",
"Zwischensequenz der Kampagne Stille Grenze: Soldaten im Südgraben des Niemandslands.":"“寂静边境”战役过场动画：无人区南战壕中的士兵。",
