"vom Host":"由房主设定",
"von Anthropic. Lesen und verstehen kann ich Code, ihn selbst zu schreiben liegt mir aber nicht. Diesen Teil hat Claude übernommen und meine Vorstellungen Zeile für Zeile umgesetzt. Da in NULLPUNKT fast alles aus Code entsteht, gilt das auch für Modelle, Karten und Klänge: gebaut nach meinen Vorgaben und so lange nachgebessert, bis sie gepasst haben. Ergänzt wird das durch freie Texturen und Umgebungslicht von Poly Haven und ambientCG.":"出自 Anthropic。我能读懂代码，但自己写代码不是我的强项。这部分由 Claude 负责，一行一行地实现了我的设想。由于 NULLPUNKT 中几乎一切都由代码生成，模型、地图和音效也是如此：按照我的要求制作，并反复打磨直到满意。此外还使用了来自 Poly Haven 和 ambientCG 的免费纹理与环境光照。",
